import { InventoryRecord } from './types';
import { RAW_CSV_DATA } from './constants';

export const parseCSV = (): InventoryRecord[] => {
  const lines = RAW_CSV_DATA.trim().split('\n');
  const records: InventoryRecord[] = [];

  // Skip the first two header rows and start from index 2
  for (let i = 2; i < lines.length; i++) {
    const line = lines[i];
    // Simple regex to handle comma separation while respecting quotes
    const matches = line.match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g);

    // Fallback split if regex fails or simple line
    const values = line.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/);

    if (values.length < 20) continue; // Basic validation

    const clean = (val: string) => val ? val.replace(/^"|"$/g, '').replace(/""/g, '"').trim() : '';
    const num = (val: string) => parseInt(clean(val) || '0', 10);

    records.push({
      itemId: clean(values[0]),
      itemName: clean(values[1]),
      brandName: clean(values[2]),
      upc: clean(values[3]),
      uom: clean(values[4]),
      warehouseId: clean(values[5]),
      warehouseName: clean(values[6]),
      netScheduled: num(values[7]),
      incomingScheduled: num(values[8]),
      recalled: num(values[9]),
      totalSellable: num(values[10]),
      sellableWarehouse: num(values[11]),
      sellableInBetween: num(values[12]),
      sellableDarkstore: num(values[13]),
      totalUnsellable: num(values[14]),
      unsellableDamaged: num(values[15]),
      unsellableLost: num(values[16]),
      unsellableExpired: num(values[17]),
      unsellableNearExpiry: num(values[18]),
      soldLast7: num(values[19]),
      soldLast15: num(values[20]),
      soldLast30: num(values[21]),
    });
  }
  return records;
};

export const aggregateByItem = (records: InventoryRecord[]) => {
  const map = new Map<string, InventoryRecord & { warehouseCount: number }>();

  records.forEach(r => {
    if (!map.has(r.itemId)) {
      map.set(r.itemId, { ...r, warehouseCount: 1 });
    } else {
      const existing = map.get(r.itemId)!;
      existing.totalSellable += r.totalSellable;
      existing.totalUnsellable += r.totalUnsellable;
      existing.sellableDarkstore += r.sellableDarkstore;
      existing.unsellableDamaged += r.unsellableDamaged;
      existing.unsellableLost += r.unsellableLost;
      existing.soldLast7 += r.soldLast7;
      existing.soldLast15 += r.soldLast15;
      existing.soldLast30 += r.soldLast30;
      existing.warehouseCount += 1;
    }
  });

  return Array.from(map.values());
};

export const aggregateByWarehouse = (records: InventoryRecord[]) => {
  const map = new Map<string, { name: string; sellable: number; unsellable: number; sold30: number }>();

  records.forEach(r => {
    if (!map.has(r.warehouseName)) {
      map.set(r.warehouseName, { name: r.warehouseName, sellable: 0, unsellable: 0, sold30: 0 });
    }
    const w = map.get(r.warehouseName)!;
    w.sellable += r.totalSellable;
    w.unsellable += r.totalUnsellable;
    w.sold30 += r.soldLast30;
  });

  return Array.from(map.values());
};

