};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { InventoryTable } from './components/InventoryTable';
import { parseCSV } from './utils';
import { InventoryRecord, ViewMode } from './types';

const App: React.FC = () => {
  const [data, setData] = useState<InventoryRecord[]>([]);
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.DASHBOARD);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Simulate loading delay for realistic feel
    const timer = setTimeout(() => {
      const records = parseCSV();
      setData(records);
      setLoading(false);
    }, 800);

    return () => clearTimeout(timer);
  }, []);

  if (loading) {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-gray-50">
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-yellow-400"></div>
          <p className="text-gray-500 font-medium animate-pulse">Loading Inventory Data...</p>
        </div>
      </div>
    );
  }

  return (
    <Layout currentMode={viewMode} setMode={setViewMode}>
      {viewMode === ViewMode.DASHBOARD ? (
        <Dashboard data={data} />
      ) : (
        <InventoryTable data={data} />
      )}
    </Layout>
  );
};

