}

import { InventoryRecord, SalesRecord, MergedItem } from './types';
import { RAW_CSV_DATA } from './constants';

// Helper to read file as text
export const readFileAsText = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => resolve(e.target?.result as string);
    reader.onerror = (e) => reject(e);
    reader.readAsText(file);
  });
};

const cleanString = (val: string) => val ? val.replace(/^"|"$/g, '').replace(/""/g, '"').trim() : '';
const parseNum = (val: string) => parseInt(cleanString(val) || '0', 10);

export const parseInventoryCSV = (csvContent: string): InventoryRecord[] => {
  const lines = csvContent.trim().split('\n');
  const records: InventoryRecord[] = [];

  // Finding the header row index (usually contains "Item ID")
  let headerIndex = -1;
  for(let i=0; i<Math.min(lines.length, 10); i++) {
     if(lines[i].toLowerCase().includes('item id') && lines[i].toLowerCase().includes('warehouse')) {
        headerIndex = i;
        break;
     }
  }

  // If no standard header found, assume standard format starting at index 2 like RAW_CSV_DATA
  const startIndex = headerIndex !== -1 ? headerIndex + 1 : 2;

  for (let i = startIndex; i < lines.length; i++) {
    const line = lines[i];
    // Simple regex to handle comma separation while respecting quotes
    const values = line.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/);

    if (values.length < 10) continue; 

    records.push({
      itemId: cleanString(values[0]),
      itemName: cleanString(values[1]),
      brandName: cleanString(values[2]),
      upc: cleanString(values[3]),
      uom: cleanString(values[4]),
      warehouseId: cleanString(values[5]),
      warehouseName: cleanString(values[6]),
      netScheduled: parseNum(values[7]),
      incomingScheduled: parseNum(values[8]),
      recalled: parseNum(values[9]),
      totalSellable: parseNum(values[10]),
      sellableWarehouse: parseNum(values[11]),
      sellableInBetween: parseNum(values[12]),
      sellableDarkstore: parseNum(values[13]),
      totalUnsellable: parseNum(values[14]),
      unsellableDamaged: parseNum(values[15]),
      unsellableLost: parseNum(values[16]),
      unsellableExpired: parseNum(values[17]),
      unsellableNearExpiry: parseNum(values[18]),
      soldLast7: parseNum(values[19]),
      soldLast15: parseNum(values[20]),
      soldLast30: parseNum(values[21]),
    });
  }
  return records;
};

export const parseSalesCSV = (csvContent: string): SalesRecord[] => {
  const lines = csvContent.trim().split('\n');
  const records: SalesRecord[] = [];

  // Basic heuristic to find headers
  let idIndex = 0;
  let qtyIndex = 1;
  let revIndex = -1;
  let nameIndex = -1;
  let brandIndex = -1;

  const headerRow = lines.find(l => l.toLowerCase().includes('item id') || l.toLowerCase().includes('sku'));

  if (headerRow) {
     const headers = headerRow.toLowerCase().split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/).map(h => h.trim().replace(/"/g, ''));
     idIndex = headers.findIndex(h => h.toLowerCase().includes('item id') || h.toLowerCase().includes('sku') || h.toLowerCase().includes('identifier'));
     qtyIndex = headers.findIndex(h => h.toLowerCase().includes('quantity') || h.toLowerCase().includes('qty') || h.toLowerCase().includes('sold') || h.toLowerCase().includes('units'));
     revIndex = headers.findIndex(h => h.toLowerCase().includes('bill amount') || h.toLowerCase().includes('revenue') || h.toLowerCase().includes('total amount'));
     nameIndex = headers.findIndex(h => h.toLowerCase().includes('product name') || h.toLowerCase().includes('item name'));
     brandIndex = headers.findIndex(h => h.toLowerCase().includes('brand name'));
  }

  // Start reading after header
  const startIndex = lines.indexOf(headerRow!) + 1 || 1;

  for (let i = startIndex; i < lines.length; i++) {
    const line = lines[i];
    const values = line.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/);

    if (values.length <= Math.max(idIndex, qtyIndex)) continue;

    records.push({
      itemId: cleanString(values[idIndex]),
      itemName: nameIndex > -1 ? cleanString(values[nameIndex]) : undefined,
      brandName: brandIndex > -1 ? cleanString(values[brandIndex]) : undefined,
      quantity: parseNum(values[qtyIndex]),
      revenue: revIndex > -1 ? parseFloat(cleanString(values[revIndex])) : 0
    });
  }

  return records;
};

// Merge logic
export const mergeData = (inventory: InventoryRecord[], sales: SalesRecord[]): MergedItem[] => {
  const map = new Map<string, MergedItem>();

  // Process Inventory First
  inventory.forEach(inv => {
    if (!map.has(inv.itemId)) {
      map.set(inv.itemId, {
        itemId: inv.itemId,
        itemName: inv.itemName,
        brandName: inv.brandName,
        totalSellable: 0,
        totalUnsellable: 0,
        salesVelocity: 0,
        inventoryRunway: 0,
        warehouseDistribution: {},
        stockStatus: 'Healthy'
      });
    }
    const item = map.get(inv.itemId)!;
    item.totalSellable += inv.totalSellable;
    item.totalUnsellable += inv.totalUnsellable;

    if (!item.warehouseDistribution[inv.warehouseName]) {
       item.warehouseDistribution[inv.warehouseName] = 0;
    }
    item.warehouseDistribution[inv.warehouseName] += inv.totalSellable;
  });

  // Process Sales
  if (sales.length > 0) {
    sales.forEach(sale => {
      // Create item from sales record if not exists (Stockout items)
      if (!map.has(sale.itemId)) {
        map.set(sale.itemId, {
          itemId: sale.itemId,
          itemName: sale.itemName || `Unknown Item (${sale.itemId})`,
          brandName: sale.brandName || 'Unknown',
          totalSellable: 0,
          totalUnsellable: 0,
          salesVelocity: 0,
          inventoryRunway: 0, // 0 stock / X sales = 0 days
          warehouseDistribution: {},
          stockStatus: 'Stockout'
        });
      }

      const item = map.get(sale.itemId)!;
      item.salesVelocity += sale.quantity;
    });
  } else {
     // Fallback to inventory sheet columns if no separate sales sheet provided
     inventory.forEach(inv => {
        if (map.has(inv.itemId)) {
           const item = map.get(inv.itemId)!;
           // Avoid double counting if multiple warehouses list same item
           // Using simple aggregation from the provided CSV structure where sales columns repeat per warehouse row
           // For safety, we treat the 'soldLast30' as the source of truth if sales file is missing
           // Note: In some reports, sales columns might be total or per warehouse. 
           // Given the prompt, we prioritize the Sales File for velocity.
           // If using inventory only, we take the max value seen for an item ID across rows to avoid summing duplicates if the report repeats totals, 
           // OR sum them if they are per-warehouse. Standard practice varies. 
           // Looking at sample data: 10202646 has soldLast30=1 in rows 1 and 2, but 28 in row 3 (Mumbai). 
           // It seems strictly per warehouse row. So summing is correct.
           item.salesVelocity += (inv.soldLast30 || 0);
        }
     });
  }

  // Calculate Derived Metrics
  map.forEach(item => {
    // Inventory Runway (Days of stock)
    // Daily Sales = salesVelocity / 30
    const dailySales = item.salesVelocity / 30;
    item.inventoryRunway = dailySales > 0 ? Math.floor(item.totalSellable / dailySales) : 999;

    // Set Status
    if (item.totalSellable === 0 && item.salesVelocity > 0) item.stockStatus = 'Stockout';
    else if (item.inventoryRunway < 7 && item.salesVelocity > 0) item.stockStatus = 'Low';
    else if (item.inventoryRunway > 60) item.stockStatus = 'Overstocked';
    else item.stockStatus = 'Healthy';
  });

  return Array.from(map.values());
};

export const aggregateByWarehouse = (records: InventoryRecord[]) => {
  const map = new Map<string, { name: string; sellable: number; unsellable: number }>();

  records.forEach(r => {
    if (!map.has(r.warehouseName)) {
      map.set(r.warehouseName, { name: r.warehouseName, sellable: 0, unsellable: 0 });
    }
    const w = map.get(r.warehouseName)!;
    w.sellable += r.totalSellable;
    w.unsellable += r.totalUnsellable;
  });

  return Array.from(map.values());
};

import React, { useState, useMemo } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { InventoryTable } from './components/InventoryTable';
import { DataImport } from './components/DataImport';
import { parseInventoryCSV, parseSalesCSV, readFileAsText, mergeData } from './utils';
import { InventoryRecord, SalesRecord, ViewMode, DataSource, FileType } from './types';
import { RAW_CSV_DATA, RAW_SALES_DATA } from './constants';

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.DATA_IMPORT);
  const [inventoryData, setInventoryData] = useState<InventoryRecord[]>([]);
  const [salesData, setSalesData] = useState<SalesRecord[]>([]);
  const [sources, setSources] = useState<DataSource[]>([]);
  const [loading, setLoading] = useState(false);

  // Derived merged data for dashboard
  const mergedData = useMemo(() => {
    const activeInventory = sources.find(s => s.type === 'INVENTORY' && s.isActive) ? inventoryData : [];
    const activeSales = sources.find(s => s.type === 'SALES' && s.isActive) ? salesData : [];

    // If no active data at all, return empty
    if (activeInventory.length === 0 && activeSales.length === 0) return [];

    return mergeData(activeInventory, activeSales);
  }, [inventoryData, salesData, sources]);

  const handleFileUpload = async (file: File, type: FileType) => {
    setLoading(true);
    try {
      const content = await readFileAsText(file);
      const newSource: DataSource = {
        id: Date.now().toString(),
        type,
        fileName: file.name,
        uploadDate: Date.now(),
        isActive: true,
        rowCount: 0
      };

      if (type === 'INVENTORY') {
        const records = parseInventoryCSV(content);
        setInventoryData(records);
        newSource.rowCount = records.length;
        // Replace existing inventory source if any
        setSources(prev => [...prev.filter(s => s.type !== 'INVENTORY'), newSource]);
      } else {
        const records = parseSalesCSV(content);
        setSalesData(records);
        newSource.rowCount = records.length;
        // Replace existing sales source if any
        setSources(prev => [...prev.filter(s => s.type !== 'SALES'), newSource]);
      }

      // Auto switch to dashboard if data looks good
      if (sources.length >= 0) { 
        setTimeout(() => setViewMode(ViewMode.DASHBOARD), 500);
      }

    } catch (error) {
      console.error("Failed to parse file", error);
      alert("Error parsing file. Please check format.");
    } finally {
      setLoading(false);
    }
  };

  const handleLoadSample = () => {
    setLoading(true);
    setTimeout(() => {
      // Load Inventory
      const invRecords = parseInventoryCSV(RAW_CSV_DATA);
      setInventoryData(invRecords);

      // Load Sales
      const salesRecords = parseSalesCSV(RAW_SALES_DATA);
      setSalesData(salesRecords);

      setSources(prev => [
        // Remove old demos if any
        ...prev.filter(s => !s.id.startsWith('demo-')),
        {
          id: 'demo-inventory',
          type: 'INVENTORY',
          fileName: 'Demo_Inventory_Data.csv',
          uploadDate: Date.now(),
          isActive: true,
          rowCount: invRecords.length
        },
        {
          id: 'demo-sales',
          type: 'SALES',
          fileName: 'Demo_Monthly_Sales.csv',
          uploadDate: Date.now(),
          isActive: true,
          rowCount: salesRecords.length
        }
      ]);
      setLoading(false);
      setViewMode(ViewMode.DASHBOARD);
    }, 800);
  };

  const handleRemoveSource = (id: string) => {
    setSources(prev => prev.filter(s => s.id !== id));
    // Clear data if source removed
    const source = sources.find(s => s.id === id);
    if (source?.type === 'INVENTORY') setInventoryData([]);
    if (source?.type === 'SALES') setSalesData([]);
  };

  const handleToggleSource = (id: string) => {
    setSources(prev => prev.map(s => s.id === id ? { ...s, isActive: !s.isActive } : s));
  };

  if (loading) {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-gray-50">
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-yellow-400"></div>
          <p className="text-gray-500 font-medium animate-pulse">Processing Data...</p>
        </div>
      </div>
    );
  }

  return (
    <Layout currentMode={viewMode} setMode={setViewMode}>
      {viewMode === ViewMode.DASHBOARD && (
        sources.some(s => s.isActive) ? (
          <Dashboard mergedData={mergedData} rawInventory={inventoryData} />
        ) : (
          <div className="flex flex-col items-center justify-center h-full text-gray-400">
             <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 text-center max-w-md">
                <p className="text-lg font-medium text-gray-800 mb-2">Ready to Analyze?</p>
                <p className="text-gray-500 mb-6">Upload your inventory and sales reports to see the insights.</p>
                <button 
                  onClick={() => setViewMode(ViewMode.DATA_IMPORT)} 
                  className="px-6 py-2 bg-yellow-400 text-slate-900 font-bold rounded-lg hover:bg-yellow-300 transition-colors"
                >
                  Go to Import
                </button>
             </div>
          </div>
        )
      )}

      {viewMode === ViewMode.INVENTORY_LIST && (
        <InventoryTable data={inventoryData} />
      )}

      {viewMode === ViewMode.DATA_IMPORT && (
        <DataImport 
          sources={sources} 
          onUpload={handleFileUpload} 
          onRemove={handleRemoveSource}
          onToggle={handleToggleSource}
          onLoadSample={handleLoadSample}
        />
      )}
    </Layout>
  );
};

