import React, { useState, useMemo } from 'react';
import { InventoryRecord } from '../types';
import { Search, ArrowUpDown, ArrowDown, ArrowUp, Filter, IndianRupee } from 'lucide-react';

interface InventoryTableProps {
  data: InventoryRecord[];
}

type SortField = keyof InventoryRecord | 'revenue'; // extended for display purposes
type SortOrder = 'asc' | 'desc';

export const InventoryTable: React.FC<InventoryTableProps> = ({ data }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [sortField, setSortField] = useState<SortField>('totalSellable');
  const [sortOrder, setSortOrder] = useState<SortOrder>('desc');
  const [showFilters, setShowFilters] = useState(false);

  // Filters State
  const [filters, setFilters] = useState({
    brand: 'All',
    warehouse: 'All',
  });

  // Extract Unique Values
  const uniqueBrands = useMemo(() => Array.from(new Set(data.map(i => i.brandName))).sort(), [data]);
  const uniqueWarehouses = useMemo(() => Array.from(new Set(data.map(i => i.warehouseName))).sort(), [data]);

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('desc');
    }
  };

  const filteredData = data
    .filter(item => {
        const matchesSearch = item.itemName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                              item.itemId.includes(searchTerm);
        const matchesBrand = filters.brand === 'All' || item.brandName === filters.brand;
        const matchesWarehouse = filters.warehouse === 'All' || item.warehouseName === filters.warehouse;

        return matchesSearch && matchesBrand && matchesWarehouse;
    })
    .sort((a, b) => {
      const aValue = a[sortField as keyof InventoryRecord];
      const bValue = b[sortField as keyof InventoryRecord];

      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortOrder === 'asc' ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
      }

      return sortOrder === 'asc' 
        ? (aValue as number) - (bValue as number) 
        : (bValue as number) - (aValue as number);
    });

  const SortIcon = ({ field }: { field: SortField }) => {
    if (sortField !== field) return <ArrowUpDown className="w-4 h-4 text-gray-300" />;
    return sortOrder === 'asc' 
      ? <ArrowUp className="w-4 h-4 text-blue-600" /> 
      : <ArrowDown className="w-4 h-4 text-blue-600" />;
  };

  return (
    <div className="space-y-4">
      {/* Header & Search */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-4">
            <h2 className="text-xl font-bold text-gray-800">Raw Inventory Data</h2>
            <div className="flex gap-2 w-full md:w-auto">
                <button 
                    onClick={() => setShowFilters(!showFilters)}
                    className={`px-4 py-2 rounded-lg border flex items-center gap-2 text-sm font-medium transition-colors ${showFilters ? 'bg-slate-100 border-slate-300' : 'bg-white border-gray-200 hover:bg-gray-50'}`}
                >
                    <Filter className="w-4 h-4" />
                    Filters
                </button>
                <div className="relative flex-1 md:w-80">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                    <input
                        type="text"
                        placeholder="Search Product Name or ID..."
                        className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
            </div>
        </div>

        {/* Expandable Filter Panel */}
        {showFilters && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-4 border-t border-gray-100 animate-in slide-in-from-top-1">
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Warehouse</label>
                    <select 
                        className="w-full p-2 border border-gray-200 rounded-lg text-sm outline-none focus:border-blue-500"
                        value={filters.warehouse}
                        onChange={(e) => setFilters({...filters, warehouse: e.target.value})}
                    >
                        <option value="All">All Warehouses</option>
                        {uniqueWarehouses.map(w => <option key={w} value={w}>{w}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Brand</label>
                    <select 
                        className="w-full p-2 border border-gray-200 rounded-lg text-sm outline-none focus:border-blue-500"
                        value={filters.brand}
                        onChange={(e) => setFilters({...filters, brand: e.target.value})}
                    >
                        <option value="All">All Brands</option>
                        {uniqueBrands.map(b => <option key={b} value={b}>{b}</option>)}
                    </select>
                </div>
                <div className="flex items-end">
                    <button 
                        onClick={() => setFilters({brand: 'All', warehouse: 'All'})}
                        className="text-sm text-blue-600 hover:underline px-2 py-2"
                    >
                        Clear Filters
                    </button>
                </div>
            </div>
        )}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-50 text-gray-600 font-medium border-b border-gray-200">
              <tr>
                <th className="px-6 py-4 cursor-pointer hover:bg-gray-100" onClick={() => handleSort('itemName')}>
                  <div className="flex items-center gap-2">Product Details <SortIcon field="itemName" /></div>
                </th>
                <th className="px-6 py-4 cursor-pointer hover:bg-gray-100" onClick={() => handleSort('warehouseName')}>
                   <div className="flex items-center gap-2">Warehouse <SortIcon field="warehouseName" /></div>
                </th>
                <th className="px-6 py-4 text-right cursor-pointer hover:bg-gray-100" onClick={() => handleSort('totalSellable')}>
                   <div className="flex items-center justify-end gap-2">Sellable <SortIcon field="totalSellable" /></div>
                </th>
                 <th className="px-6 py-4 text-right cursor-pointer hover:bg-gray-100" onClick={() => handleSort('sellableDarkstore')}>
                   <div className="flex items-center justify-end gap-2">Darkstore <SortIcon field="sellableDarkstore" /></div>
                </th>
                <th className="px-6 py-4 text-right cursor-pointer hover:bg-gray-100" onClick={() => handleSort('totalUnsellable')}>
                   <div className="flex items-center justify-end gap-2">Unsellable <SortIcon field="totalUnsellable" /></div>
                </th>
                <th className="px-6 py-4 text-right cursor-pointer hover:bg-gray-100" onClick={() => handleSort('unsellableDamaged')}>
                   <div className="flex items-center justify-end gap-2">Damaged <SortIcon field="unsellableDamaged" /></div>
                </th>
                <th className="px-6 py-4 text-right cursor-pointer hover:bg-gray-100" onClick={() => handleSort('soldLast30')}>
                   <div className="flex items-center justify-end gap-2">Sold (30d) <SortIcon field="soldLast30" /></div>
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredData.map((record, idx) => (
                <tr key={`${record.itemId}-${record.warehouseId}-${idx}`} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4 max-w-xs">
                    <div className="font-medium text-gray-900 truncate" title={record.itemName}>{record.itemName}</div>
                    <div className="text-xs text-gray-500 mt-0.5">ID: {record.itemId} | {record.brandName}</div>
                  </td>
                  <td className="px-6 py-4 text-gray-600">{record.warehouseName}</td>
                  <td className="px-6 py-4 text-right font-medium text-green-600 bg-green-50/50">{record.totalSellable}</td>
                  <td className="px-6 py-4 text-right text-gray-600">{record.sellableDarkstore}</td>
                  <td className="px-6 py-4 text-right font-medium text-red-600 bg-red-50/50">{record.totalUnsellable}</td>
                  <td className="px-6 py-4 text-right text-gray-600">{record.unsellableDamaged}</td>
                  <td className="px-6 py-4 text-right text-blue-600 font-medium">{record.soldLast30}</td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-6 py-12 text-center text-gray-400">
                    No records found matching your filters.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { InventoryTable } from './components/InventoryTable';
import { DataImport } from './components/DataImport';
import { parseInventoryCSV, parseSalesCSV, readFileAsText, readExcelAsCSV, mergeData } from './utils';
import { InventoryRecord, SalesRecord, ViewMode, DataSource, FileType } from './types';
import { RAW_CSV_DATA, RAW_SALES_DATA } from './constants';

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.DATA_IMPORT);
  const [inventoryData, setInventoryData] = useState<InventoryRecord[]>([]);
  const [salesData, setSalesData] = useState<SalesRecord[]>([]);
  const [sources, setSources] = useState<DataSource[]>([]);
  const [loading, setLoading] = useState(false);

  // Derived merged data for dashboard
  const mergedData = useMemo(() => {
    const activeInventory = sources.find(s => s.type === 'INVENTORY' && s.isActive) ? inventoryData : [];
    const activeSales = sources.find(s => s.type === 'SALES' && s.isActive) ? salesData : [];

    // If no active data at all, return empty
    if (activeInventory.length === 0 && activeSales.length === 0) return [];

    return mergeData(activeInventory, activeSales);
  }, [inventoryData, salesData, sources]);

  const handleFileUpload = async (file: File, type: FileType) => {
    try {
      let content = '';

      // Check file extension
      if (file.name.endsWith('.csv')) {
        content = await readFileAsText(file);
      } else if (file.name.match(/\.(xlsx|xls)$/)) {
        content = await readExcelAsCSV(file);
      } else {
        throw new Error("Unsupported file format. Please upload .csv, .xlsx, or .xls");
      }

      const newSource: DataSource = {
        id: Date.now().toString(),
        type,
        fileName: file.name,
        uploadDate: Date.now(),
        isActive: true,
        rowCount: 0
      };

      if (type === 'INVENTORY') {
        const records = parseInventoryCSV(content); 
        setInventoryData(records);
        newSource.rowCount = records.length;
        setSources(prev => [...prev.filter(s => s.type !== 'INVENTORY'), newSource]);
      } else {
        const records = parseSalesCSV(content); 
        setSalesData(records);
        newSource.rowCount = records.length;
        setSources(prev => [...prev.filter(s => s.type !== 'SALES'), newSource]);
      }

    } catch (error: any) {
      console.error("File processing error:", error);
      throw error; 
    }
  };

  const handleLoadSample = () => {
    setLoading(true);
    setTimeout(() => {
      try {
        // Load Inventory
        const invRecords = parseInventoryCSV(RAW_CSV_DATA);
        setInventoryData(invRecords);

        // Load Sales
        const salesRecords = parseSalesCSV(RAW_SALES_DATA);
        setSalesData(salesRecords);

        setSources(prev => [
          ...prev.filter(s => !s.id.startsWith('demo-')),
          {
            id: 'demo-inventory',
            type: 'INVENTORY',
            fileName: 'Demo_Inventory_Data.csv',
            uploadDate: Date.now(),
            isActive: true,
            rowCount: invRecords.length
          },
          {
            id: 'demo-sales',
            type: 'SALES',
            fileName: 'Demo_Monthly_Sales.csv',
            uploadDate: Date.now(),
            isActive: true,
            rowCount: salesRecords.length
          }
        ]);
        setViewMode(ViewMode.DASHBOARD);
      } catch (e) {
        console.error("Error loading sample data", e);
      } finally {
        setLoading(false);
      }
    }, 800);
  };

  const handleRemoveSource = (id: string) => {
    setSources(prev => prev.filter(s => s.id !== id));
    const source = sources.find(s => s.id === id);
    if (source?.type === 'INVENTORY') setInventoryData([]);
    if (source?.type === 'SALES') setSalesData([]);
  };

  const handleToggleSource = (id: string) => {
    setSources(prev => prev.map(s => s.id === id ? { ...s, isActive: !s.isActive } : s));
  };

  if (loading) {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-gray-50">
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-yellow-400"></div>
          <p className="text-gray-500 font-medium animate-pulse">Setting up Dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <Layout currentMode={viewMode} setMode={setViewMode}>
      {viewMode === ViewMode.DASHBOARD && (
        sources.some(s => s.isActive) ? (
          <Dashboard 
            mergedData={mergedData} 
            rawInventory={inventoryData} 
            salesData={salesData}
          />
        ) : (
          <div className="flex flex-col items-center justify-center h-full text-gray-400">
             <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 text-center max-w-md">
                <p className="text-lg font-medium text-gray-800 mb-2">Ready to Analyze?</p>
                <p className="text-gray-500 mb-6">Upload your inventory and sales reports to see the insights.</p>
                <button 
                  onClick={() => setViewMode(ViewMode.DATA_IMPORT)} 
                  className="px-6 py-2 bg-yellow-400 text-slate-900 font-bold rounded-lg hover:bg-yellow-300 transition-colors"
                >
                  Go to Import
                </button>
             </div>
          </div>
        )
      )}

      {viewMode === ViewMode.INVENTORY_LIST && (
        <InventoryTable data={inventoryData} />
      )}

      {viewMode === ViewMode.DATA_IMPORT && (
        <DataImport 
          sources={sources} 
          onUpload={handleFileUpload} 
          onRemove={handleRemoveSource}
          onToggle={handleToggleSource}
          onLoadSample={handleLoadSample}
        />
      )}
    </Layout>
  );
};

export default App;

import React from 'react';

export interface InventoryRecord {
  itemId: string;
  itemName: string;
  brandName: string;
  upc: string;
  uom: string;
  warehouseId: string;
  warehouseName: string;
  netScheduled: number;
  incomingScheduled: number;
  recalled: number;
  totalSellable: number;
  sellableWarehouse: number;
  sellableInBetween: number;
  sellableDarkstore: number;
  totalUnsellable: number;
  unsellableDamaged: number;
  unsellableLost: number;
  unsellableExpired: number;
  unsellableNearExpiry: number;
  soldLast7?: number;
  soldLast15?: number;
  soldLast30?: number;
}

export interface SalesRecord {
  itemId: string;
  itemName?: string;
  brandName?: string;
  quantity: number;
  revenue: number;
  date?: string; // YYYY-MM-DD
}

export interface MergedItem {
  itemId: string;
  itemName: string;
  brandName: string;
  totalSellable: number;
  totalUnsellable: number;
  salesVelocity: number; 
  totalRevenue: number; 
  inventoryRunway: number; 
  warehouseDistribution: { [key: string]: number };
  stockStatus: 'Healthy' | 'Overstocked' | 'Stockout' | 'Low';
}

export interface ChartDataPoint {
  date: string;
  revenue: number;
  quantity: number;
  label: string;
}

export interface DataSource {
  id: string;
  type: FileType;
  fileName: string;
  uploadDate: number;
  isActive: boolean;
  rowCount: number;
  rawContent?: string; // Added to support re-processing
}

export type FileType = 'INVENTORY' | 'SALES';

export enum ViewMode {
  DASHBOARD = 'DASHBOARD',
  INVENTORY_LIST = 'INVENTORY_LIST',
  DATA_IMPORT = 'DATA_IMPORT',
}

import React, { useState, useMemo, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { InventoryTable } from './components/InventoryTable';
import { DataImport } from './components/DataImport';
import { parseInventoryCSV, parseSalesCSV, readFileAsText, readExcelAsCSV, mergeData } from './utils';
import { InventoryRecord, SalesRecord, ViewMode, DataSource, FileType } from './types';
import { RAW_CSV_DATA, RAW_SALES_DATA } from './constants';

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.DATA_IMPORT);
  const [inventoryData, setInventoryData] = useState<InventoryRecord[]>([]);
  const [salesData, setSalesData] = useState<SalesRecord[]>([]);
  const [sources, setSources] = useState<DataSource[]>([]);
  const [loading, setLoading] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Initialize theme from system preference or default to light
  useEffect(() => {
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setIsDarkMode(true);
    }
  }, []);

  // Derived merged data for dashboard
  const mergedData = useMemo(() => {
    const activeInventory = sources.find(s => s.type === 'INVENTORY' && s.isActive) ? inventoryData : [];
    const activeSales = sources.find(s => s.type === 'SALES' && s.isActive) ? salesData : [];

    if (activeInventory.length === 0 && activeSales.length === 0) return [];

    return mergeData(activeInventory, activeSales);
  }, [inventoryData, salesData, sources]);

  const processFileContent = (content: string, type: FileType, fileName: string) => {
    const newSource: DataSource = {
      id: Date.now().toString(),
      type,
      fileName,
      uploadDate: Date.now(),
      isActive: true,
      rowCount: 0,
      rawContent: content
    };

    if (type === 'INVENTORY') {
      const records = parseInventoryCSV(content); 
      setInventoryData(records);
      newSource.rowCount = records.length;
      setSources(prev => [...prev.filter(s => s.type !== 'INVENTORY'), newSource]);
    } else {
      const records = parseSalesCSV(content); 
      setSalesData(records);
      newSource.rowCount = records.length;
      setSources(prev => [...prev.filter(s => s.type !== 'SALES'), newSource]);
    }
  };

  const handleFileUpload = async (file: File, type: FileType) => {
    try {
      let content = '';
      if (file.name.endsWith('.csv')) {
        content = await readFileAsText(file);
      } else if (file.name.match(/\.(xlsx|xls)$/)) {
        content = await readExcelAsCSV(file);
      } else {
        throw new Error("Unsupported file format. Please upload .csv, .xlsx, or .xls");
      }
      processFileContent(content, type, file.name);
    } catch (error: any) {
      console.error("File processing error:", error);
      throw error; 
    }
  };

  const handleLoadSample = () => {
    setLoading(true);
    setTimeout(() => {
      try {
        processFileContent(RAW_CSV_DATA, 'INVENTORY', 'Demo_Inventory_Data.csv');
        processFileContent(RAW_SALES_DATA, 'SALES', 'Demo_Monthly_Sales.csv');
        // Clean up duplicate demo entries if any (processFileContent adds new ones)
        // Ideally we structure this better, but for demo:
        setSources(prev => {
           // Keep only the latest of each type
           const inv = prev.filter(s => s.type === 'INVENTORY').pop();
           const sales = prev.filter(s => s.type === 'SALES').pop();
           return [inv, sales].filter(Boolean) as DataSource[];
        });
        setViewMode(ViewMode.DASHBOARD);
      } catch (e) {
        console.error("Error loading sample data", e);
      } finally {
        setLoading(false);
      }
    }, 800);
  };

  const handleRefreshData = async () => {
    setLoading(true);
    try {
      // Simulate processing time
      await new Promise(resolve => setTimeout(resolve, 600));

      // Re-parse all active sources
      sources.forEach(source => {
        if (source.rawContent) {
          if (source.type === 'INVENTORY') {
            const records = parseInventoryCSV(source.rawContent);
            setInventoryData(records);
          } else {
            const records = parseSalesCSV(source.rawContent);
            setSalesData(records);
          }
        }
      });
      alert("Data refreshed successfully.");
    } catch (e) {
      console.error("Refresh failed", e);
      alert("Failed to refresh data.");
    } finally {
      setLoading(false);
    }
  };

  const handleRemoveSource = (id: string) => {
    setSources(prev => prev.filter(s => s.id !== id));
    const source = sources.find(s => s.id === id);
    if (source?.type === 'INVENTORY') setInventoryData([]);
    if (source?.type === 'SALES') setSalesData([]);
  };

  const handleToggleSource = (id: string) => {
    setSources(prev => prev.map(s => s.id === id ? { ...s, isActive: !s.isActive } : s));
  };

  if (loading) {
    return (
      <div className={`h-screen w-full flex items-center justify-center ${isDarkMode ? 'bg-slate-900' : 'bg-gray-50'}`}>
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-yellow-400"></div>
          <p className={`font-medium animate-pulse ${isDarkMode ? 'text-slate-400' : 'text-gray-500'}`}>Processing Data...</p>
        </div>
      </div>
    );
  }

  return (
    <Layout currentMode={viewMode} setMode={setViewMode} isDarkMode={isDarkMode} toggleTheme={() => setIsDarkMode(!isDarkMode)}>
      {viewMode === ViewMode.DASHBOARD && (
        sources.some(s => s.isActive) ? (
          <Dashboard 
            mergedData={mergedData} 
            rawInventory={inventoryData} 
            salesData={salesData}
          />
        ) : (
          <div className="flex flex-col items-center justify-center h-full text-gray-400 dark:text-slate-500">
             <div className="bg-white dark:bg-slate-800 p-8 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700 text-center max-w-md transition-colors">
                <p className="text-lg font-medium text-gray-800 dark:text-white mb-2">Ready to Analyze?</p>
                <p className="text-gray-500 dark:text-slate-400 mb-6">Upload your inventory and sales reports to see the insights.</p>
                <button 
                  onClick={() => setViewMode(ViewMode.DATA_IMPORT)} 
                  className="px-6 py-2 bg-yellow-400 text-slate-900 font-bold rounded-lg hover:bg-yellow-300 transition-colors"
                >
                  Go to Import
                </button>
             </div>
          </div>
        )
      )}

      {viewMode === ViewMode.INVENTORY_LIST && (
        <InventoryTable data={inventoryData} />
      )}

      {viewMode === ViewMode.DATA_IMPORT && (
        <DataImport 
          sources={sources} 
          onUpload={handleFileUpload} 
          onRemove={handleRemoveSource}
          onToggle={handleToggleSource}
          onLoadSample={handleLoadSample}
          onRefresh={handleRefreshData}
        />
      )}
    </Layout>
  );
};

export default App;

