import React, { useState } from 'react';
import { Upload, FileText, Trash2, Eye, EyeOff, CheckCircle, FileSpreadsheet, AlertCircle, X, RefreshCw } from 'lucide-react';
import { DataSource, FileType } from '../types';

interface DataImportProps {
  sources: DataSource[];
  onUpload: (file: File, type: FileType) => Promise<void>;
  onRemove: (id: string) => void;
  onToggle: (id: string) => void;
  onLoadSample: () => void;
  onRefresh: () => void;
}

export const DataImport: React.FC<DataImportProps> = ({ sources, onUpload, onRemove, onToggle, onLoadSample, onRefresh }) => {
  const [uploadingType, setUploadingType] = useState<FileType | null>(null);
  const [error, setError] = useState<{ type: FileType; message: string } | null>(null);
  const [progress, setProgress] = useState(0);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, type: FileType) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setUploadingType(type);
      setError(null);
      setProgress(0);

      const interval = setInterval(() => {
        setProgress(prev => {
          if (prev >= 90) return prev;
          return prev + 10;
        });
      }, 100);

      try {
        await onUpload(file, type);
        setProgress(100);
      } catch (err: any) {
        setError({ type, message: err.message || "Failed to parse file." });
      } finally {
        clearInterval(interval);
        setTimeout(() => {
          setUploadingType(null);
          setProgress(0);
        }, 500);
      }
    }
  };

  const UploadCard = ({ type, title, description, allowedExts }: { type: FileType, title: string, description: string, allowedExts: string }) => {
    const existing = sources.find(s => s.type === type);
    const isUploading = uploadingType === type;
    const hasError = error?.type === type;

    return (
      <div className={`p-6 rounded-xl border-2 border-dashed transition-all relative overflow-hidden ${
        existing 
          ? 'border-green-200 bg-green-50 dark:bg-green-900/10 dark:border-green-800' 
          : hasError 
            ? 'border-red-200 bg-red-50 dark:bg-red-900/10 dark:border-red-800' 
            : 'border-gray-200 hover:border-yellow-400 bg-white dark:bg-slate-800 dark:border-slate-700 dark:hover:border-yellow-500'
      }`}>
        {/* Loading Overlay */}
        {isUploading && (
          <div className="absolute inset-0 bg-white/90 dark:bg-slate-800/90 z-10 flex flex-col items-center justify-center p-6">
            <div className="w-full max-w-[200px] h-2 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden mb-3">
              <div 
                className="h-full bg-yellow-400 transition-all duration-300 ease-out"
                style={{ width: `${progress}%` }}
              />
            </div>
            <p className="text-sm font-medium text-gray-600 dark:text-gray-300 animate-pulse">Processing File...</p>
          </div>
        )}

        <div className="flex items-start justify-between mb-4">
          <div className="flex items-center gap-3">
             <div className={`p-3 rounded-lg ${
               existing ? 'bg-green-100 text-green-600 dark:bg-green-900 dark:text-green-400' : 
               hasError ? 'bg-red-100 text-red-600 dark:bg-red-900 dark:text-red-400' : 'bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400'
             }`}>
               {existing ? <CheckCircle className="w-6 h-6" /> : <FileSpreadsheet className="w-6 h-6" />}
             </div>
             <div>
               <h3 className="font-bold text-gray-800 dark:text-gray-100">{title}</h3>
               <p className="text-sm text-gray-500 dark:text-gray-400 max-w-xs">{description}</p>
             </div>
          </div>
          {existing && !isUploading && (
            <div className="flex gap-2">
               <button 
                  onClick={() => onToggle(existing.id)}
                  className="p-2 text-gray-500 hover:text-blue-600 hover:bg-white dark:text-gray-400 dark:hover:text-blue-400 dark:hover:bg-slate-700 rounded-lg transition-colors"
                  title={existing.isActive ? "Hide Data" : "Show Data"}
                >
                  {existing.isActive ? <Eye className="w-5 h-5" /> : <EyeOff className="w-5 h-5" />}
               </button>
               <button 
                  onClick={() => onRemove(existing.id)}
                  className="p-2 text-gray-500 hover:text-red-600 hover:bg-white dark:text-gray-400 dark:hover:text-red-400 dark:hover:bg-slate-700 rounded-lg transition-colors"
                  title="Remove File"
                >
                  <Trash2 className="w-5 h-5" />
               </button>
            </div>
          )}
        </div>

        {hasError && (
          <div className="mb-4 p-3 bg-red-100 dark:bg-red-900/30 border border-red-200 dark:border-red-800 rounded-lg flex items-start gap-2 text-sm text-red-700 dark:text-red-300 animate-in slide-in-from-top-2">
            <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="font-semibold">Error Uploading File</p>
              <p className="mt-1">{error.message}</p>
            </div>
            <button onClick={() => setError(null)} className="text-red-500 hover:text-red-800 dark:hover:text-red-300">
              <X className="w-4 h-4" />
            </button>
          </div>
        )}

        {existing ? (
          <div className="mt-4 p-3 bg-white/60 dark:bg-slate-900/50 rounded-lg border border-green-100 dark:border-green-800/30">
            <div className="flex justify-between items-center text-sm">
              <span className="font-medium text-gray-700 dark:text-gray-300 truncate max-w-[150px]" title={existing.fileName}>{existing.fileName}</span>
              <span className="text-green-700 dark:text-green-400 font-medium bg-green-100 dark:bg-green-900/50 px-2 py-0.5 rounded text-xs">{existing.rowCount.toLocaleString()} rows</span>
            </div>
            <div className="mt-1 text-xs text-gray-400 dark:text-gray-500">
               Uploaded: {new Date(existing.uploadDate).toLocaleTimeString()}
               {!existing.isActive && <span className="ml-2 text-red-500 font-medium">(Hidden)</span>}
            </div>
          </div>
        ) : (
          <div className="mt-4">
            <label className="flex items-center justify-center w-full px-4 py-3 bg-white dark:bg-slate-700 border border-gray-200 dark:border-slate-600 rounded-lg shadow-sm cursor-pointer hover:bg-gray-50 dark:hover:bg-slate-600 transition-colors group">
              <Upload className="w-5 h-5 mr-2 text-gray-400 dark:text-gray-300 group-hover:text-yellow-500 dark:group-hover:text-yellow-400" />
              <span className="text-sm font-medium text-gray-600 dark:text-gray-200 group-hover:text-gray-900 dark:group-hover:text-white">Upload {allowedExts}</span>
              <input 
                type="file" 
                className="hidden" 
                accept=".csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel" 
                onChange={(e) => handleFileChange(e, type)} 
              />
            </label>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Data Management</h2>
          <p className="text-gray-500 dark:text-gray-400 mt-1">Upload your inventory and sales reports (Excel or CSV) to generate analytics.</p>
        </div>
        {sources.length > 0 && (
          <button 
            onClick={onRefresh}
            className="flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-gray-700 dark:text-gray-200 rounded-lg transition-colors text-sm font-medium"
          >
            <RefreshCw className="w-4 h-4" />
            Refresh Data
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <UploadCard 
          type="INVENTORY" 
          title="Warehouse Stock" 
          description="Upload 'Inventory' sheet with warehouse stock levels, expiry dates, and damaged units."
          allowedExts="CSV or Excel"
        />
        <UploadCard 
          type="SALES" 
          title="Monthly Sales" 
          description="Upload 'Sales' report containing Item IDs and Quantity Sold. Used for velocity calculations."
          allowedExts="CSV or Excel"
        />
      </div>

      <div className="pt-8 border-t border-gray-200 dark:border-slate-800">
        <div className="bg-gradient-to-r from-slate-900 to-slate-800 rounded-xl p-6 text-white flex items-center justify-between shadow-lg">
          <div>
            <h3 className="font-bold text-lg">Don't have files handy?</h3>
            <p className="text-slate-300 text-sm mt-1">Load sample Blinkit seller data to preview the dashboard.</p>
          </div>
          <button 
            onClick={onLoadSample}
            className="px-6 py-2 bg-yellow-400 text-slate-900 font-bold rounded-lg hover:bg-yellow-300 transition-colors shadow-lg hover:shadow-yellow-400/20"
          >
            Load Demo Data
          </button>
        </div>
      </div>

      {sources.length === 0 && (
         <div className="text-center py-12 text-gray-400 dark:text-slate-600">
            <div className="mb-3">
               <FileText className="w-12 h-12 mx-auto opacity-20" />
            </div>
            <p>No data sources active. Please upload files or load demo data.</p>
         </div>
      )}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { InventoryRecord, MergedItem, SalesRecord } from '../types';
import { aggregateByWarehouse, prepareSalesChartData } from '../utils';
import { 
