        setProgress(100);
        // Reset file input value so same file can be selected again if needed (though logic handles dupes)
        e.target.value = '';
      } catch (err: any) {
        setError({ type, message: err.message || "Failed to parse file." });
      } finally {
        clearInterval(interval);
        setTimeout(() => {
          setUploadingType(null);
          setProgress(0);
        }, 500);
      }
    }
  };

  const UploadCard = ({ type, title, description, allowedExts, multiple }: { type: FileType, title: string, description: string, allowedExts: string, multiple: boolean }) => {
    const existingFiles = sources.filter(s => s.type === type);
    const isUploading = uploadingType === type;
    const hasError = error?.type === type;

    // For single file mode (Inventory), showing input if no file exists.
    // For multiple file mode (Sales), always show input (as 'Add More').
    const showInput = multiple || existingFiles.length === 0;

    return (
      <div className={`flex flex-col h-full p-6 rounded-xl border-2 border-dashed transition-all relative overflow-hidden ${
        existingFiles.length > 0
          ? 'border-green-200 bg-green-50 dark:bg-green-900/10 dark:border-green-800' 
          : hasError 
            ? 'border-red-200 bg-red-50 dark:bg-red-900/10 dark:border-red-800' 
            : 'border-gray-200 hover:border-yellow-400 bg-white dark:bg-slate-800 dark:border-slate-700 dark:hover:border-yellow-500'
      }`}>
        {/* Loading Overlay */}
        {isUploading && (
          <div className="absolute inset-0 bg-white/90 dark:bg-slate-800/90 z-20 flex flex-col items-center justify-center p-6">
            <div className="w-full max-w-[200px] h-2 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden mb-3">
              <div 
                className="h-full bg-yellow-400 transition-all duration-300 ease-out"
                style={{ width: `${progress}%` }}
              />
            </div>
            <p className="text-sm font-medium text-gray-600 dark:text-gray-300 animate-pulse">Processing File...</p>
          </div>
        )}

        <div className="flex items-start justify-between mb-4">
          <div className="flex items-center gap-3">
             <div className={`p-3 rounded-lg ${
               existingFiles.length > 0 ? 'bg-green-100 text-green-600 dark:bg-green-900 dark:text-green-400' : 
               hasError ? 'bg-red-100 text-red-600 dark:bg-red-900 dark:text-red-400' : 'bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400'
             }`}>
               {existingFiles.length > 0 ? <CheckCircle className="w-6 h-6" /> : <FileSpreadsheet className="w-6 h-6" />}
             </div>
             <div>
               <h3 className="font-bold text-gray-800 dark:text-gray-100">{title}</h3>
               <p className="text-sm text-gray-500 dark:text-gray-400 max-w-xs">{description}</p>
             </div>
          </div>
        </div>

        {hasError && (
          <div className="mb-4 p-3 bg-red-100 dark:bg-red-900/30 border border-red-200 dark:border-red-800 rounded-lg flex items-start gap-2 text-sm text-red-700 dark:text-red-300 animate-in slide-in-from-top-2">
            <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="font-semibold">Error Uploading File</p>
              <p className="mt-1">{error.message}</p>
            </div>
            <button onClick={() => setError(null)} className="text-red-500 hover:text-red-800 dark:hover:text-red-300">
              <X className="w-4 h-4" />
            </button>
          </div>
        )}

        {/* List of uploaded files */}
        <div className="flex-1 space-y-2 mb-4">
          {existingFiles.map(file => (
            <div key={file.id} className="p-3 bg-white/60 dark:bg-slate-900/50 rounded-lg border border-green-100 dark:border-green-800/30 flex justify-between items-center animate-in fade-in slide-in-from-bottom-1">
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  <span className={`font-medium text-sm truncate ${!file.isActive ? 'text-gray-400 line-through' : 'text-gray-700 dark:text-gray-300'}`} title={file.fileName}>
                    {file.fileName}
                  </span>
                  {!file.isActive && <span className="text-xs text-red-500 font-medium">(Hidden)</span>}
                </div>
                <div className="text-xs text-gray-400 dark:text-gray-500 mt-0.5">
                   {file.rowCount.toLocaleString()} rows • {new Date(file.uploadDate).toLocaleTimeString()}
                </div>
              </div>
              <div className="flex gap-1 ml-2">
                 <button 
                    onClick={() => onToggle(file.id)}
                    className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-white dark:hover:bg-slate-700 rounded transition-colors"
                    title={file.isActive ? "Hide Data" : "Show Data"}
                  >
                    {file.isActive ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                 </button>
                 <button 
                    onClick={() => onRemove(file.id)}
                    className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-white dark:hover:bg-slate-700 rounded transition-colors"
                    title="Remove File"
                  >
                    <Trash2 className="w-4 h-4" />
                 </button>
              </div>
            </div>
          ))}
        </div>

        {/* Upload Button */}
        {showInput && (
          <div className="mt-auto">
            <label className={`flex items-center justify-center w-full px-4 py-3 border border-gray-200 dark:border-slate-600 rounded-lg shadow-sm cursor-pointer transition-colors group ${
              multiple && existingFiles.length > 0 
                ? 'bg-slate-50 dark:bg-slate-800 border-dashed hover:bg-slate-100 dark:hover:bg-slate-700' 
                : 'bg-white dark:bg-slate-700 hover:bg-gray-50 dark:hover:bg-slate-600'
            }`}>
              {multiple && existingFiles.length > 0 ? (
                 <Plus className="w-5 h-5 mr-2 text-gray-400 dark:text-gray-300 group-hover:text-green-500" />
              ) : (
                 <Upload className="w-5 h-5 mr-2 text-gray-400 dark:text-gray-300 group-hover:text-yellow-500" />
              )}
              <span className="text-sm font-medium text-gray-600 dark:text-gray-200 group-hover:text-gray-900 dark:group-hover:text-white">
                {multiple && existingFiles.length > 0 ? "Add Another Report" : `Upload ${allowedExts}`}
              </span>
              <input 
                type="file" 
                className="hidden" 
                accept=".csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel" 
                onChange={(e) => handleFileChange(e, type)} 
              />
            </label>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Data Management</h2>
          <p className="text-gray-500 dark:text-gray-400 mt-1">Upload your inventory and sales reports (Excel or CSV) to generate analytics.</p>
        </div>
        {sources.length > 0 && (
          <button 
            onClick={onRefresh}
            className="flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-gray-700 dark:text-gray-200 rounded-lg transition-colors text-sm font-medium"
          >
            <RefreshCw className="w-4 h-4" />
            Refresh Data
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <UploadCard 
          type="INVENTORY" 
          title="Warehouse Stock" 
          description="Upload 'Inventory' sheet with warehouse stock levels. (Single File)"
          allowedExts="CSV or Excel"
          multiple={false}
        />
        <UploadCard 
          type="SALES" 
          title="Sales Reports" 
          description="Upload one or more 'Sales' reports to aggregate sales velocity and revenue."
          allowedExts="CSV or Excel"
          multiple={true}
        />
      </div>

      <div className="pt-8 border-t border-gray-200 dark:border-slate-800">
        <div className="bg-gradient-to-r from-slate-900 to-slate-800 rounded-xl p-6 text-white flex items-center justify-between shadow-lg">
          <div>
            <h3 className="font-bold text-lg">Don't have files handy?</h3>
            <p className="text-slate-300 text-sm mt-1">Load sample Blinkit seller data to preview the dashboard.</p>
          </div>
          <button 
            onClick={onLoadSample}
            className="px-6 py-2 bg-yellow-400 text-slate-900 font-bold rounded-lg hover:bg-yellow-300 transition-colors shadow-lg hover:shadow-yellow-400/20"
          >
            Load Demo Data
          </button>
        </div>
      </div>

      {sources.length === 0 && (
         <div className="text-center py-12 text-gray-400 dark:text-slate-600">
            <div className="mb-3">
               <FileText className="w-12 h-12 mx-auto opacity-20" />
            </div>
            <p>No data sources active. Please upload files or load demo data.</p>
         </div>
      )}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { InventoryRecord, MergedItem, SalesRecord } from '../types';
import { aggregateByWarehouse, prepareSalesChartData } from '../utils';
import { 
  ComposedChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell, Area
} from 'recharts';
import { Package, AlertTriangle, TrendingUp, ArchiveX, Filter, IndianRupee, X, Download } from 'lucide-react';

interface DashboardProps {
  mergedData: MergedItem[];
  rawInventory: InventoryRecord[];
  salesData: SalesRecord[];
}

const COLORS = ['#10B981', '#F59E0B', '#EF4444', '#3B82F6', '#8B5CF6'];
const STATUS_COLORS: {[key: string]: string} = {
  'Healthy': '#10B981',
  'Overstocked': '#F59E0B',
  'Low Stock': '#3B82F6',
  'Stockout': '#EF4444'
};

export const Dashboard: React.FC<DashboardProps> = ({ mergedData, rawInventory, salesData }) => {
  const [chartPeriod, setChartPeriod] = useState<'daily' | 'weekly' | 'monthly'>('daily');
  const [filters, setFilters] = useState({
    brand: 'All',
    status: 'All',
    warehouse: 'All'
  });
  const [showFilters, setShowFilters] = useState(false);

  // --- Derived Data for Filters ---
  const uniqueBrands = useMemo(() => Array.from(new Set(mergedData.map(i => i.brandName))).sort(), [mergedData]);
  const uniqueWarehouses = useMemo(() => Array.from(new Set(rawInventory.map(i => i.warehouseName))).sort(), [rawInventory]);

  // --- Filter Logic ---
  const filteredData = useMemo(() => {
    return mergedData.filter(item => {
      const matchBrand = filters.brand === 'All' || item.brandName === filters.brand;
      const matchStatus = filters.status === 'All' || item.stockStatus === filters.status;
      const matchWarehouse = filters.warehouse === 'All' || item.warehouseDistribution[filters.warehouse] > 0;
      return matchBrand && matchStatus && matchWarehouse;
    });
  }, [mergedData, filters, rawInventory]);

  // Filter raw inventory for Warehouse chart
  const filteredInventory = useMemo(() => {
    return rawInventory.filter(item => {
      const matchBrand = filters.brand === 'All' || item.brandName === filters.brand;
      const matchWarehouse = filters.warehouse === 'All' || item.warehouseName === filters.warehouse;
      return matchBrand && matchWarehouse;
    });
  }, [rawInventory, filters]);

  // Filter sales data for charts (by Brand only as Warehouse ID missing in Sales)
  const filteredSales = useMemo(() => {
    return salesData.filter(sale => {
      const matchBrand = filters.brand === 'All' || (sale.brandName && sale.brandName === filters.brand);
      return matchBrand;
    });
  }, [salesData, filters.brand]);

  // --- Aggregations ---
  const warehouseStats = useMemo(() => aggregateByWarehouse(filteredInventory), [filteredInventory]);
  const chartData = useMemo(() => prepareSalesChartData(filteredSales), [filteredSales]);

  // KPIs
  const totalSellable = filteredData.reduce((sum, r) => sum + r.totalSellable, 0);
  const totalUnsellable = filteredData.reduce((sum, r) => sum + r.totalUnsellable, 0);
  const totalRevenue = filteredData.reduce((sum, r) => sum + r.totalRevenue, 0);
  const totalSalesVelocity = filteredData.reduce((sum, r) => sum + r.salesVelocity, 0);

  const unsellableRatio = totalSellable + totalUnsellable > 0 
    ? ((totalUnsellable / (totalSellable + totalUnsellable)) * 100).toFixed(1)
    : "0";

  // Top Selling Items (by Revenue)
  const topRevenueItems = [...filteredData]
    .sort((a, b) => b.totalRevenue - a.totalRevenue)
    .slice(0, 5)
    .map(item => ({
      name: item.itemName.length > 20 ? item.itemName.substring(0, 20) + '...' : item.itemName,
      revenue: item.totalRevenue,
      qty: item.salesVelocity
    }));

  // Stock Status Distribution
  const stockStatusData = [
    { name: 'Healthy', value: filteredData.filter(i => i.stockStatus === 'Healthy').length },
    { name: 'Overstocked', value: filteredData.filter(i => i.stockStatus === 'Overstocked').length },
    { name: 'Low Stock', value: filteredData.filter(i => i.stockStatus === 'Low').length },
    { name: 'Stockout', value: filteredData.filter(i => i.stockStatus === 'Stockout').length },
  ].filter(x => x.value > 0);

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0
    }).format(val);
  };

  const handleExportChartData = () => {
    const data = chartData[chartPeriod];
    if (!data || data.length === 0) return;

    const csvRows = [
      ['Date', 'Period Label', 'Revenue (INR)', 'Units Sold'],
      ...data.map(row => [
        row.date,
        row.label,
        row.revenue,
        row.quantity
      ])
    ];

    const csvContent = "data:text/csv;charset=utf-8," + csvRows.map(e => e.join(",")).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `blinkit_sales_trend_${chartPeriod}_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Inventory & Sales Intelligence</h2>
          <p className="text-sm text-gray-500 dark:text-gray-400">Analysis based on imported Sales Report & Inventory Sheet</p>
        </div>
        <button 
          onClick={() => setShowFilters(!showFilters)}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-colors ${
            showFilters 
              ? 'bg-slate-800 text-white dark:bg-yellow-400 dark:text-slate-900 font-medium' 
              : 'bg-white dark:bg-slate-800 border border-gray-300 dark:border-slate-700 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-slate-700'
          }`}
        >
          <Filter className="w-4 h-4" />
          Filters {filters.brand !== 'All' || filters.status !== 'All' || filters.warehouse !== 'All' ? '(Active)' : ''}
        </button>
      </div>

      {/* Multi-Filter Panel */}
      {showFilters && (
        <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-yellow-200 dark:border-yellow-500/30 animate-in slide-in-from-top-2">
          <div className="flex justify-between items-center mb-3">
            <h3 className="text-sm font-bold text-gray-700 dark:text-gray-200 uppercase tracking-wide">Filter Analysis Data</h3>
            <button onClick={() => setFilters({brand: 'All', status: 'All', warehouse: 'All'})} className="text-xs text-blue-600 dark:text-blue-400 hover:underline">Reset All</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Brand</label>
              <select 
                className="w-full p-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm outline-none focus:border-yellow-400 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                value={filters.brand}
                onChange={(e) => setFilters({...filters, brand: e.target.value})}
              >
                <option value="All">All Brands</option>
                {uniqueBrands.map(b => <option key={b} value={b}>{b}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Stock Status</label>
              <select 
                className="w-full p-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm outline-none focus:border-yellow-400 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                value={filters.status}
                onChange={(e) => setFilters({...filters, status: e.target.value})}
              >
                <option value="All">All Statuses</option>
                <option value="Healthy">Healthy</option>
                <option value="Overstocked">Overstocked</option>
                <option value="Low Stock">Low Stock</option>
                <option value="Stockout">Stockout</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Warehouse</label>
              <select 
                className="w-full p-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm outline-none focus:border-yellow-400 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                value={filters.warehouse}
                onChange={(e) => setFilters({...filters, warehouse: e.target.value})}
              >
                <option value="All">All Locations</option>
                {uniqueWarehouses.map(w => <option key={w} value={w}>{w}</option>)}
              </select>
            </div>
          </div>
        </div>
      )}

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Revenue</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{formatCurrency(totalRevenue)}</p>
            <div className="flex items-center gap-1 mt-2 text-xs font-medium text-green-600 dark:text-green-400">
               <span className="bg-green-50 dark:bg-green-900/30 px-1.5 py-0.5 rounded">From Sales Report</span>
            </div>
          </div>
          <div className="bg-green-50 dark:bg-green-900/20 p-3 rounded-lg">
            <IndianRupee className="w-6 h-6 text-green-600 dark:text-green-400" />
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Sales Velocity (Qty)</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{totalSalesVelocity.toLocaleString()}</p>
            <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">Total Units Sold</p>
          </div>
          <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-lg">
            <TrendingUp className="w-6 h-6 text-blue-600 dark:text-blue-400" />
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Active Inventory</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{totalSellable.toLocaleString()}</p>
            <div className="flex items-center gap-1 mt-2 text-xs font-medium text-orange-600 dark:text-orange-400">
               <span className="bg-orange-50 dark:bg-orange-900/30 px-1.5 py-0.5 rounded">Sellable Units</span>
            </div>
          </div>
          <div className="bg-orange-50 dark:bg-orange-900/20 p-3 rounded-lg">
            <Package className="w-6 h-6 text-orange-600 dark:text-orange-400" />
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Unsellable Ratio</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{unsellableRatio}%</p>
             <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">{totalUnsellable} units total</p>
          </div>
          <div className="bg-red-50 dark:bg-red-900/20 p-3 rounded-lg">
            <ArchiveX className="w-6 h-6 text-red-600 dark:text-red-400" />
          </div>
        </div>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Sales Timeline Chart - Dual Axis (Revenue + Units) */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 lg:col-span-2 transition-colors">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
            <div>
               <h3 className="text-lg font-bold text-gray-800 dark:text-white">Revenue & Volume Trend</h3>
               <p className="text-xs text-gray-500 dark:text-gray-400">Blue Area: Revenue (₹) • Bars: Units Sold</p>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={handleExportChartData}
                className="p-1.5 text-gray-400 hover:text-blue-600 dark:text-gray-500 dark:hover:text-blue-400 transition-colors"
                title="Export Data to CSV"
              >
                <Download className="w-4 h-4" />
              </button>
              <div className="flex bg-gray-100 dark:bg-slate-700 rounded-lg p-1">
                {['daily', 'weekly', 'monthly'].map((period) => (
                  <button
                    key={period}
                    onClick={() => setChartPeriod(period as any)}
                    className={`px-3 py-1 text-xs font-medium rounded-md capitalize transition-all ${
                      chartPeriod === period 
                        ? 'bg-white dark:bg-slate-600 text-blue-600 dark:text-blue-400 shadow-sm' 
                        : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'
                    }`}
                  >
                    {period}
                  </button>
                ))}
              </div>
            </div>
          </div>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={chartData[chartPeriod]} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3B82F6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3B82F6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E5E7EB" className="dark:stroke-slate-700" />
                <XAxis dataKey="label" tick={{ fontSize: 11, fill: '#94a3b8' }} minTickGap={30} axisLine={false} tickLine={false} />

                {/* Left Axis: Revenue */}
                <YAxis 
                  yAxisId="left"
                  tickFormatter={(val) => `₹${val/1000}k`} 
                  tick={{ fontSize: 11, fill: '#3B82F6' }} 
                  axisLine={false} 
                  tickLine={false} 
                />

                {/* Right Axis: Units */}
                <YAxis 
                  yAxisId="right" 
                  orientation="right" 
                  tick={{ fontSize: 11, fill: '#F59E0B' }} 
                  axisLine={false} 
                  tickLine={false} 
                  allowDecimals={false}
                />

                <Tooltip 
                  formatter={(value: number, name: string) => {
                     if (name === 'revenue') return [formatCurrency(value), 'Revenue'];
                     if (name === 'quantity') return [value, 'Units Sold'];
                     return [value, name];
                  }}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', backgroundColor: '#fff' }} 
                />
                <Legend iconType="circle" wrapperStyle={{ fontSize: '12px', paddingTop: '10px' }} />

                <Area yAxisId="left" type="monotone" dataKey="revenue" name="Revenue (₹)" stroke="#3B82F6" strokeWidth={2} fillOpacity={1} fill="url(#colorRevenue)" />
                <Bar yAxisId="right" dataKey="quantity" name="Units Sold" fill="#F59E0B" barSize={20} radius={[4, 4, 0, 0]} />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Top Revenue Items */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 transition-colors">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4">Top Revenue Drivers</h3>
          <div className="h-80 overflow-y-auto pr-2 custom-scrollbar">
             {topRevenueItems.map((item, idx) => (
                <div key={idx} className="mb-4 last:mb-0">
                   <div className="flex justify-between items-start mb-1">
                      <span className="text-sm font-medium text-gray-800 dark:text-gray-200 truncate max-w-[180px]" title={item.name}>{item.name}</span>
                      <span className="text-sm font-bold text-green-600 dark:text-green-400">{formatCurrency(item.revenue)}</span>
                   </div>
                   <div className="w-full bg-gray-100 dark:bg-slate-700 rounded-full h-1.5 mb-1">
                      <div className="bg-green-500 h-1.5 rounded-full" style={{ width: `${Math.min(100, (item.revenue / (topRevenueItems[0]?.revenue || 1)) * 100)}%` }}></div>
                   </div>
                   <p className="text-xs text-gray-400 dark:text-gray-500">{item.qty} units sold</p>
                </div>
             ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Stock Status Breakdown */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 transition-colors">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4">Stock Health Distribution</h3>
          <div className="flex items-center">
            <div className="h-56 w-1/2">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={stockStatusData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={80}
                    paddingAngle={2}
                    dataKey="value"
                    stroke="none"
                  >
                    {stockStatusData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={STATUS_COLORS[entry.name]} />
                    ))}
                  </Pie>
                  <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="w-1/2 space-y-3">
               {stockStatusData.map((item) => (
                  <div key={item.name} className="flex items-center justify-between text-sm">
                     <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: STATUS_COLORS[item.name] }}></div>
                        <span className="text-gray-600 dark:text-gray-300">{item.name}</span>
                     </div>
                     <span className="font-semibold text-gray-900 dark:text-white">{item.value}</span>
                  </div>
               ))}
            </div>
          </div>
        </div>

        {/* Warehouse Stock */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 transition-colors">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4">Stock by Warehouse (Filtered)</h3>
          <div className="h-56">
             <ResponsiveContainer width="100%" height="100%">
               <BarChart data={warehouseStats} layout="vertical" margin={{ top: 0, right: 30, left: 40, bottom: 0 }}>
                 <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#E5E7EB" className="dark:stroke-slate-700" />
                 <XAxis type="number" hide />
                 <YAxis type="category" dataKey="name" width={120} tick={{ fontSize: 10, fill: '#94a3b8' }} axisLine={false} tickLine={false} />
                 <Tooltip cursor={{fill: 'transparent'}} contentStyle={{ borderRadius: '8px' }} />
                 <Legend wrapperStyle={{ fontSize: '11px' }}/>
                 <Bar dataKey="sellable" name="Sellable" stackId="a" fill="#10B981" radius={[0, 4, 4, 0]} barSize={12} />
                 <Bar dataKey="unsellable" name="Unsellable" stackId="a" fill="#EF4444" radius={[0, 4, 4, 0]} barSize={12} />
               </BarChart>
             </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { InventoryRecord, MergedItem, SalesRecord } from '../types';
import { aggregateByWarehouse, prepareSalesChartData } from '../utils';
import { 
  ComposedChart, Bar, BarChart, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell, Area
} from 'recharts';
import { Package, AlertTriangle, TrendingUp, ArchiveX, Filter, IndianRupee, X, Download } from 'lucide-react';

interface DashboardProps {
  mergedData: MergedItem[];
  rawInventory: InventoryRecord[];
  salesData: SalesRecord[];
}

const COLORS = ['#10B981', '#F59E0B', '#EF4444', '#3B82F6', '#8B5CF6'];
const STATUS_COLORS: {[key: string]: string} = {
  'Healthy': '#10B981',
  'Overstocked': '#F59E0B',
  'Low Stock': '#3B82F6',
  'Stockout': '#EF4444'
};

export const Dashboard: React.FC<DashboardProps> = ({ mergedData, rawInventory, salesData }) => {
  const [chartPeriod, setChartPeriod] = useState<'daily' | 'weekly' | 'monthly'>('daily');
  const [filters, setFilters] = useState({
    brand: 'All',
    status: 'All',
    warehouse: 'All'
  });
  const [showFilters, setShowFilters] = useState(false);

  // --- Derived Data for Filters ---
  const uniqueBrands = useMemo(() => Array.from(new Set(mergedData.map(i => i.brandName))).sort(), [mergedData]);
  const uniqueWarehouses = useMemo(() => Array.from(new Set(rawInventory.map(i => i.warehouseName))).sort(), [rawInventory]);

  // --- Filter Logic ---
  const filteredData = useMemo(() => {
    return mergedData.filter(item => {
      const matchBrand = filters.brand === 'All' || item.brandName === filters.brand;
      const matchStatus = filters.status === 'All' || item.stockStatus === filters.status;
      const matchWarehouse = filters.warehouse === 'All' || item.warehouseDistribution[filters.warehouse] > 0;
      return matchBrand && matchStatus && matchWarehouse;
    });
  }, [mergedData, filters, rawInventory]);

  // Filter raw inventory for Warehouse chart
  const filteredInventory = useMemo(() => {
    return rawInventory.filter(item => {
      const matchBrand = filters.brand === 'All' || item.brandName === filters.brand;
      const matchWarehouse = filters.warehouse === 'All' || item.warehouseName === filters.warehouse;
      return matchBrand && matchWarehouse;
    });
  }, [rawInventory, filters]);

  // Filter sales data for charts (by Brand only as Warehouse ID missing in Sales)
  const filteredSales = useMemo(() => {
    return salesData.filter(sale => {
      const matchBrand = filters.brand === 'All' || (sale.brandName && sale.brandName === filters.brand);
      return matchBrand;
    });
  }, [salesData, filters.brand]);

  // --- Aggregations ---
  const warehouseStats = useMemo(() => aggregateByWarehouse(filteredInventory), [filteredInventory]);
  const chartData = useMemo(() => prepareSalesChartData(filteredSales), [filteredSales]);

  // KPIs
  const totalSellable = filteredData.reduce((sum, r) => sum + r.totalSellable, 0);
  const totalUnsellable = filteredData.reduce((sum, r) => sum + r.totalUnsellable, 0);
  const totalRevenue = filteredData.reduce((sum, r) => sum + r.totalRevenue, 0);
  const totalSalesVelocity = filteredData.reduce((sum, r) => sum + r.salesVelocity, 0);

  const unsellableRatio = totalSellable + totalUnsellable > 0 
    ? ((totalUnsellable / (totalSellable + totalUnsellable)) * 100).toFixed(1)
    : "0";

  // Top Selling Items (by Revenue)
  const topRevenueItems = [...filteredData]
    .sort((a, b) => b.totalRevenue - a.totalRevenue)
    .slice(0, 5)
    .map(item => ({
      name: item.itemName.length > 20 ? item.itemName.substring(0, 20) + '...' : item.itemName,
      revenue: item.totalRevenue,
      qty: item.salesVelocity
    }));

  // Stock Status Distribution
  const stockStatusData = [
    { name: 'Healthy', value: filteredData.filter(i => i.stockStatus === 'Healthy').length },
    { name: 'Overstocked', value: filteredData.filter(i => i.stockStatus === 'Overstocked').length },
    { name: 'Low Stock', value: filteredData.filter(i => i.stockStatus === 'Low').length },
    { name: 'Stockout', value: filteredData.filter(i => i.stockStatus === 'Stockout').length },
  ].filter(x => x.value > 0);

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0
    }).format(val);
  };

  const handleExportChartData = () => {
    const data = chartData[chartPeriod];
    if (!data || data.length === 0) return;

    const csvRows = [
      ['Date', 'Period Label', 'Revenue (INR)', 'Units Sold'],
      ...data.map(row => [
        row.date,
        row.label,
        row.revenue,
        row.quantity
      ])
    ];

    const csvContent = "data:text/csv;charset=utf-8," + csvRows.map(e => e.join(",")).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `blinkit_sales_trend_${chartPeriod}_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Inventory & Sales Intelligence</h2>
          <p className="text-sm text-gray-500 dark:text-gray-400">Analysis based on imported Sales Report & Inventory Sheet</p>
        </div>
        <button 
          onClick={() => setShowFilters(!showFilters)}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-colors ${
            showFilters 
              ? 'bg-slate-800 text-white dark:bg-yellow-400 dark:text-slate-900 font-medium' 
              : 'bg-white dark:bg-slate-800 border border-gray-300 dark:border-slate-700 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-slate-700'
          }`}
        >
          <Filter className="w-4 h-4" />
          Filters {filters.brand !== 'All' || filters.status !== 'All' || filters.warehouse !== 'All' ? '(Active)' : ''}
        </button>
      </div>

      {/* Multi-Filter Panel */}
      {showFilters && (
        <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-yellow-200 dark:border-yellow-500/30 animate-in slide-in-from-top-2">
          <div className="flex justify-between items-center mb-3">
            <h3 className="text-sm font-bold text-gray-700 dark:text-gray-200 uppercase tracking-wide">Filter Analysis Data</h3>
            <button onClick={() => setFilters({brand: 'All', status: 'All', warehouse: 'All'})} className="text-xs text-blue-600 dark:text-blue-400 hover:underline">Reset All</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Brand</label>
              <select 
                className="w-full p-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm outline-none focus:border-yellow-400 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                value={filters.brand}
                onChange={(e) => setFilters({...filters, brand: e.target.value})}
              >
                <option value="All">All Brands</option>
                {uniqueBrands.map(b => <option key={b} value={b}>{b}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Stock Status</label>
              <select 
                className="w-full p-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm outline-none focus:border-yellow-400 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                value={filters.status}
                onChange={(e) => setFilters({...filters, status: e.target.value})}
              >
                <option value="All">All Statuses</option>
                <option value="Healthy">Healthy</option>
                <option value="Overstocked">Overstocked</option>
                <option value="Low Stock">Low Stock</option>
                <option value="Stockout">Stockout</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Warehouse</label>
              <select 
                className="w-full p-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm outline-none focus:border-yellow-400 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                value={filters.warehouse}
                onChange={(e) => setFilters({...filters, warehouse: e.target.value})}
              >
                <option value="All">All Locations</option>
                {uniqueWarehouses.map(w => <option key={w} value={w}>{w}</option>)}
              </select>
            </div>
          </div>
        </div>
      )}

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Revenue</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{formatCurrency(totalRevenue)}</p>
            <div className="flex items-center gap-1 mt-2 text-xs font-medium text-green-600 dark:text-green-400">
               <span className="bg-green-50 dark:bg-green-900/30 px-1.5 py-0.5 rounded">From Sales Report</span>
            </div>
          </div>
          <div className="bg-green-50 dark:bg-green-900/20 p-3 rounded-lg">
            <IndianRupee className="w-6 h-6 text-green-600 dark:text-green-400" />
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Sales Velocity (Qty)</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{totalSalesVelocity.toLocaleString()}</p>
            <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">Total Units Sold</p>
          </div>
          <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-lg">
            <TrendingUp className="w-6 h-6 text-blue-600 dark:text-blue-400" />
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Active Inventory</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{totalSellable.toLocaleString()}</p>
            <div className="flex items-center gap-1 mt-2 text-xs font-medium text-orange-600 dark:text-orange-400">
               <span className="bg-orange-50 dark:bg-orange-900/30 px-1.5 py-0.5 rounded">Sellable Units</span>
            </div>
          </div>
          <div className="bg-orange-50 dark:bg-orange-900/20 p-3 rounded-lg">
            <Package className="w-6 h-6 text-orange-600 dark:text-orange-400" />
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Unsellable Ratio</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{unsellableRatio}%</p>
             <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">{totalUnsellable} units total</p>
          </div>
          <div className="bg-red-50 dark:bg-red-900/20 p-3 rounded-lg">
            <ArchiveX className="w-6 h-6 text-red-600 dark:text-red-400" />
          </div>
        </div>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Sales Timeline Chart - Dual Axis (Revenue + Units) */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 lg:col-span-2 transition-colors">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
            <div>
               <h3 className="text-lg font-bold text-gray-800 dark:text-white">Revenue & Volume Trend</h3>
               <p className="text-xs text-gray-500 dark:text-gray-400">Blue Area: Revenue (₹) • Bars: Units Sold</p>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={handleExportChartData}
                className="p-1.5 text-gray-400 hover:text-blue-600 dark:text-gray-500 dark:hover:text-blue-400 transition-colors"
                title="Export Data to CSV"
              >
                <Download className="w-4 h-4" />
              </button>
              <div className="flex bg-gray-100 dark:bg-slate-700 rounded-lg p-1">
                {['daily', 'weekly', 'monthly'].map((period) => (
                  <button
                    key={period}
                    onClick={() => setChartPeriod(period as any)}
                    className={`px-3 py-1 text-xs font-medium rounded-md capitalize transition-all ${
                      chartPeriod === period 
                        ? 'bg-white dark:bg-slate-600 text-blue-600 dark:text-blue-400 shadow-sm' 
                        : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'
                    }`}
                  >
                    {period}
                  </button>
                ))}
              </div>
            </div>
          </div>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={chartData[chartPeriod]} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3B82F6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3B82F6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E5E7EB" className="dark:stroke-slate-700" />
                <XAxis dataKey="label" tick={{ fontSize: 11, fill: '#94a3b8' }} minTickGap={30} axisLine={false} tickLine={false} />

                {/* Left Axis: Revenue */}
                <YAxis 
                  yAxisId="left"
                  tickFormatter={(val) => `₹${val/1000}k`} 
                  tick={{ fontSize: 11, fill: '#3B82F6' }} 
                  axisLine={false} 
                  tickLine={false} 
                />

                {/* Right Axis: Units */}
                <YAxis 
                  yAxisId="right" 
                  orientation="right" 
                  tick={{ fontSize: 11, fill: '#F59E0B' }} 
                  axisLine={false} 
                  tickLine={false} 
                  allowDecimals={false}
                />

                <Tooltip 
                  formatter={(value: number, name: string) => {
                     if (name === 'revenue') return [formatCurrency(value), 'Revenue'];
                     if (name === 'quantity') return [value, 'Units Sold'];
                     return [value, name];
                  }}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', backgroundColor: '#fff' }} 
                />
                <Legend iconType="circle" wrapperStyle={{ fontSize: '12px', paddingTop: '10px' }} />

                <Area yAxisId="left" type="monotone" dataKey="revenue" name="Revenue (₹)" stroke="#3B82F6" strokeWidth={2} fillOpacity={1} fill="url(#colorRevenue)" />
                <Bar yAxisId="right" dataKey="quantity" name="Units Sold" fill="#F59E0B" barSize={20} radius={[4, 4, 0, 0]} />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Top Revenue Items */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 transition-colors">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4">Top Revenue Drivers</h3>
          <div className="h-80 overflow-y-auto pr-2 custom-scrollbar">
             {topRevenueItems.map((item, idx) => (
                <div key={idx} className="mb-4 last:mb-0">
                   <div className="flex justify-between items-start mb-1">
                      <span className="text-sm font-medium text-gray-800 dark:text-gray-200 truncate max-w-[180px]" title={item.name}>{item.name}</span>
                      <span className="text-sm font-bold text-green-600 dark:text-green-400">{formatCurrency(item.revenue)}</span>
                   </div>
                   <div className="w-full bg-gray-100 dark:bg-slate-700 rounded-full h-1.5 mb-1">
                      <div className="bg-green-500 h-1.5 rounded-full" style={{ width: `${Math.min(100, (item.revenue / (topRevenueItems[0]?.revenue || 1)) * 100)}%` }}></div>
                   </div>
                   <p className="text-xs text-gray-400 dark:text-gray-500">{item.qty} units sold</p>
                </div>
             ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Stock Status Breakdown */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 transition-colors">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4">Stock Health Distribution</h3>
          <div className="flex items-center">
            <div className="h-56 w-1/2">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={stockStatusData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={80}
                    paddingAngle={2}
                    dataKey="value"
                    stroke="none"
                  >
                    {stockStatusData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={STATUS_COLORS[entry.name]} />
                    ))}
                  </Pie>
                  <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="w-1/2 space-y-3">
               {stockStatusData.map((item) => (
                  <div key={item.name} className="flex items-center justify-between text-sm">
                     <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: STATUS_COLORS[item.name] }}></div>
                        <span className="text-gray-600 dark:text-gray-300">{item.name}</span>
                     </div>
                     <span className="font-semibold text-gray-900 dark:text-white">{item.value}</span>
                  </div>
               ))}
            </div>
          </div>
        </div>

        {/* Warehouse Stock */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 transition-colors">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4">Stock by Warehouse (Filtered)</h3>
          <div className="h-56">
             <ResponsiveContainer width="100%" height="100%">
               <BarChart data={warehouseStats} layout="vertical" margin={{ top: 0, right: 30, left: 40, bottom: 0 }}>
                 <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#E5E7EB" className="dark:stroke-slate-700" />
                 <XAxis type="number" hide />
                 <YAxis type="category" dataKey="name" width={120} tick={{ fontSize: 10, fill: '#94a3b8' }} axisLine={false} tickLine={false} />
                 <Tooltip cursor={{fill: 'transparent'}} contentStyle={{ borderRadius: '8px' }} />
                 <Legend wrapperStyle={{ fontSize: '11px' }}/>
                 <Bar dataKey="sellable" name="Sellable" stackId="a" fill="#10B981" radius={[0, 4, 4, 0]} barSize={12} />
                 <Bar dataKey="unsellable" name="Unsellable" stackId="a" fill="#EF4444" radius={[0, 4, 4, 0]} barSize={12} />
               </BarChart>
             </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { InventoryRecord, MergedItem, SalesRecord } from '../types';
import { aggregateByWarehouse, prepareSalesChartData } from '../utils';
import { 
  ComposedChart, Bar, BarChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell, Area
} from 'recharts';
import { Package, AlertTriangle, TrendingUp, ArchiveX, Filter, IndianRupee, X, Download, Activity, BarChart2, Layers } from 'lucide-react';

interface DashboardProps {
  mergedData: MergedItem[];
  rawInventory: InventoryRecord[];
  salesData: SalesRecord[];
}

const COLORS = ['#10B981', '#F59E0B', '#EF4444', '#3B82F6', '#8B5CF6'];
const STATUS_COLORS: {[key: string]: string} = {
  'Healthy': '#10B981',
  'Overstocked': '#F59E0B',
  'Low Stock': '#3B82F6',
  'Stockout': '#EF4444'
};

export const Dashboard: React.FC<DashboardProps> = ({ mergedData, rawInventory, salesData }) => {
  const [chartPeriod, setChartPeriod] = useState<'daily' | 'weekly' | 'monthly'>('daily');
  const [chartType, setChartType] = useState<'mixed' | 'line' | 'bar'>('mixed');
  const [filters, setFilters] = useState({
    brand: 'All',
    status: 'All',
    warehouse: 'All'
  });
  const [showFilters, setShowFilters] = useState(false);

  // --- Derived Data for Filters ---
  const uniqueBrands = useMemo(() => Array.from(new Set(mergedData.map(i => i.brandName))).sort(), [mergedData]);
  const uniqueWarehouses = useMemo(() => Array.from(new Set(rawInventory.map(i => i.warehouseName))).sort(), [rawInventory]);

  // --- Filter Logic ---
  const filteredData = useMemo(() => {
    return mergedData.filter(item => {
      const matchBrand = filters.brand === 'All' || item.brandName === filters.brand;
      const matchStatus = filters.status === 'All' || item.stockStatus === filters.status;
      const matchWarehouse = filters.warehouse === 'All' || item.warehouseDistribution[filters.warehouse] > 0;
      return matchBrand && matchStatus && matchWarehouse;
    });
  }, [mergedData, filters, rawInventory]);

  // Filter raw inventory for Warehouse chart
  const filteredInventory = useMemo(() => {
    return rawInventory.filter(item => {
      const matchBrand = filters.brand === 'All' || item.brandName === filters.brand;
      const matchWarehouse = filters.warehouse === 'All' || item.warehouseName === filters.warehouse;
      return matchBrand && matchWarehouse;
    });
  }, [rawInventory, filters]);

  // Filter sales data for charts (by Brand only as Warehouse ID missing in Sales)
  const filteredSales = useMemo(() => {
    return salesData.filter(sale => {
      const matchBrand = filters.brand === 'All' || (sale.brandName && sale.brandName === filters.brand);
      return matchBrand;
    });
  }, [salesData, filters.brand]);

  // --- Aggregations ---
  const warehouseStats = useMemo(() => aggregateByWarehouse(filteredInventory), [filteredInventory]);
  const chartData = useMemo(() => prepareSalesChartData(filteredSales), [filteredSales]);

  // KPIs
  const totalSellable = filteredData.reduce((sum, r) => sum + r.totalSellable, 0);
  const totalUnsellable = filteredData.reduce((sum, r) => sum + r.totalUnsellable, 0);
  const totalRevenue = filteredData.reduce((sum, r) => sum + r.totalRevenue, 0);
  const totalSalesVelocity = filteredData.reduce((sum, r) => sum + r.salesVelocity, 0);

  const unsellableRatio = totalSellable + totalUnsellable > 0 
    ? ((totalUnsellable / (totalSellable + totalUnsellable)) * 100).toFixed(1)
    : "0";

  // Top Selling Items (by Revenue)
  const topRevenueItems = [...filteredData]
    .sort((a, b) => b.totalRevenue - a.totalRevenue)
    .slice(0, 5)
    .map(item => ({
      name: item.itemName.length > 20 ? item.itemName.substring(0, 20) + '...' : item.itemName,
      revenue: item.totalRevenue,
      qty: item.salesVelocity
    }));

  // Stock Status Distribution
  const stockStatusData = [
    { name: 'Healthy', value: filteredData.filter(i => i.stockStatus === 'Healthy').length },
    { name: 'Overstocked', value: filteredData.filter(i => i.stockStatus === 'Overstocked').length },
    { name: 'Low Stock', value: filteredData.filter(i => i.stockStatus === 'Low').length },
    { name: 'Stockout', value: filteredData.filter(i => i.stockStatus === 'Stockout').length },
  ].filter(x => x.value > 0);

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0
    }).format(val);
  };

  const handleExportChartData = () => {
    const data = chartData[chartPeriod];
    if (!data || data.length === 0) return;

    const csvRows = [
      ['Date', 'Period Label', 'Revenue (INR)', 'Units Sold'],
      ...data.map(row => [
        row.date,
        row.label,
        row.revenue,
        row.quantity
      ])
    ];

    const csvContent = "data:text/csv;charset=utf-8," + csvRows.map(e => e.join(",")).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `blinkit_sales_trend_${chartPeriod}_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Inventory & Sales Intelligence</h2>
          <p className="text-sm text-gray-500 dark:text-gray-400">Analysis based on imported Sales Report & Inventory Sheet</p>
        </div>
        <button 
          onClick={() => setShowFilters(!showFilters)}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-colors ${
            showFilters 
              ? 'bg-slate-800 text-white dark:bg-yellow-400 dark:text-slate-900 font-medium' 
              : 'bg-white dark:bg-slate-800 border border-gray-300 dark:border-slate-700 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-slate-700'
          }`}
        >
          <Filter className="w-4 h-4" />
          Filters {filters.brand !== 'All' || filters.status !== 'All' || filters.warehouse !== 'All' ? '(Active)' : ''}
        </button>
      </div>

      {/* Multi-Filter Panel */}
      {showFilters && (
        <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-yellow-200 dark:border-yellow-500/30 animate-in slide-in-from-top-2">
          <div className="flex justify-between items-center mb-3">
            <h3 className="text-sm font-bold text-gray-700 dark:text-gray-200 uppercase tracking-wide">Filter Analysis Data</h3>
            <button onClick={() => setFilters({brand: 'All', status: 'All', warehouse: 'All'})} className="text-xs text-blue-600 dark:text-blue-400 hover:underline">Reset All</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Brand</label>
              <select 
                className="w-full p-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm outline-none focus:border-yellow-400 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                value={filters.brand}
                onChange={(e) => setFilters({...filters, brand: e.target.value})}
              >
                <option value="All">All Brands</option>
                {uniqueBrands.map(b => <option key={b} value={b}>{b}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Stock Status</label>
              <select 
                className="w-full p-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm outline-none focus:border-yellow-400 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                value={filters.status}
                onChange={(e) => setFilters({...filters, status: e.target.value})}
              >
                <option value="All">All Statuses</option>
                <option value="Healthy">Healthy</option>
                <option value="Overstocked">Overstocked</option>
                <option value="Low Stock">Low Stock</option>
                <option value="Stockout">Stockout</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Warehouse</label>
              <select 
                className="w-full p-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm outline-none focus:border-yellow-400 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                value={filters.warehouse}
                onChange={(e) => setFilters({...filters, warehouse: e.target.value})}
              >
                <option value="All">All Locations</option>
                {uniqueWarehouses.map(w => <option key={w} value={w}>{w}</option>)}
              </select>
            </div>
          </div>
        </div>
      )}

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Revenue</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{formatCurrency(totalRevenue)}</p>
            <div className="flex items-center gap-1 mt-2 text-xs font-medium text-green-600 dark:text-green-400">
               <span className="bg-green-50 dark:bg-green-900/30 px-1.5 py-0.5 rounded">From Sales Report</span>
            </div>
          </div>
          <div className="bg-green-50 dark:bg-green-900/20 p-3 rounded-lg">
            <IndianRupee className="w-6 h-6 text-green-600 dark:text-green-400" />
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Sales Velocity (Qty)</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{totalSalesVelocity.toLocaleString()}</p>
            <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">Total Units Sold</p>
          </div>
          <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-lg">
            <TrendingUp className="w-6 h-6 text-blue-600 dark:text-blue-400" />
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Active Inventory</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{totalSellable.toLocaleString()}</p>
            <div className="flex items-center gap-1 mt-2 text-xs font-medium text-orange-600 dark:text-orange-400">
               <span className="bg-orange-50 dark:bg-orange-900/30 px-1.5 py-0.5 rounded">Sellable Units</span>
            </div>
          </div>
          <div className="bg-orange-50 dark:bg-orange-900/20 p-3 rounded-lg">
            <Package className="w-6 h-6 text-orange-600 dark:text-orange-400" />
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 flex items-center justify-between transition-colors">
          <div>
            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Unsellable Ratio</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{unsellableRatio}%</p>
             <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">{totalUnsellable} units total</p>
          </div>
          <div className="bg-red-50 dark:bg-red-900/20 p-3 rounded-lg">
            <ArchiveX className="w-6 h-6 text-red-600 dark:text-red-400" />
          </div>
        </div>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Sales Timeline Chart - Dual Axis (Revenue + Units) */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 lg:col-span-2 transition-colors">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
            <div>
               <h3 className="text-lg font-bold text-gray-800 dark:text-white">Revenue & Volume Trend</h3>
               <p className="text-xs text-gray-500 dark:text-gray-400">Comparing financial performance with sales volume over time</p>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={handleExportChartData}
                className="p-1.5 text-gray-400 hover:text-blue-600 dark:text-gray-500 dark:hover:text-blue-400 transition-colors"
                title="Export Data to CSV"
              >
                <Download className="w-4 h-4" />
              </button>

              <div className="flex bg-gray-100 dark:bg-slate-700 rounded-lg p-1">
                <button
                  onClick={() => setChartType('mixed')}
                  className={`p-1.5 rounded-md transition-all ${chartType === 'mixed' ? 'bg-white dark:bg-slate-600 text-blue-600 dark:text-blue-400 shadow-sm' : 'text-gray-400 dark:text-gray-400 hover:text-gray-700'}`}
                  title="Mixed Chart"
                >
                  <Layers className="w-4 h-4" />
                </button>
                <button
                  onClick={() => setChartType('line')}
                  className={`p-1.5 rounded-md transition-all ${chartType === 'line' ? 'bg-white dark:bg-slate-600 text-blue-600 dark:text-blue-400 shadow-sm' : 'text-gray-400 dark:text-gray-400 hover:text-gray-700'}`}
                  title="Line Chart"
                >
                  <Activity className="w-4 h-4" />
                </button>
                <button
                  onClick={() => setChartType('bar')}
                  className={`p-1.5 rounded-md transition-all ${chartType === 'bar' ? 'bg-white dark:bg-slate-600 text-blue-600 dark:text-blue-400 shadow-sm' : 'text-gray-400 dark:text-gray-400 hover:text-gray-700'}`}
                  title="Bar Chart"
                >
                  <BarChart2 className="w-4 h-4" />
                </button>
              </div>

              <div className="flex bg-gray-100 dark:bg-slate-700 rounded-lg p-1">
                {['daily', 'weekly', 'monthly'].map((period) => (
                  <button
                    key={period}
                    onClick={() => setChartPeriod(period as any)}
                    className={`px-3 py-1 text-xs font-medium rounded-md capitalize transition-all ${
                      chartPeriod === period 
                        ? 'bg-white dark:bg-slate-600 text-blue-600 dark:text-blue-400 shadow-sm' 
                        : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'
                    }`}
                  >
                    {period}
                  </button>
                ))}
              </div>
            </div>
          </div>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={chartData[chartPeriod]} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3B82F6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3B82F6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E5E7EB" className="dark:stroke-slate-700" />
                <XAxis dataKey="label" tick={{ fontSize: 11, fill: '#94a3b8' }} minTickGap={30} axisLine={false} tickLine={false} />

                {/* Left Axis: Revenue */}
                <YAxis 
                  yAxisId="left"
                  tickFormatter={(val) => `₹${val/1000}k`} 
                  tick={{ fontSize: 11, fill: '#3B82F6' }} 
                  axisLine={false} 
                  tickLine={false} 
                />

                {/* Right Axis: Units */}
                <YAxis 
                  yAxisId="right" 
                  orientation="right" 
                  tick={{ fontSize: 11, fill: '#F59E0B' }} 
                  axisLine={false} 
                  tickLine={false} 
                  allowDecimals={false}
                />

                <Tooltip 
                  formatter={(value: number, name: string) => {
                     if (name === 'revenue') return [formatCurrency(value), 'Revenue'];
                     if (name === 'quantity') return [value, 'Units Sold'];
                     return [value, name];
                  }}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', backgroundColor: '#fff' }} 
                />
                <Legend iconType="circle" wrapperStyle={{ fontSize: '12px', paddingTop: '10px' }} />

                {/* Render based on chartType */}
                {chartType === 'mixed' && (
                  <>
                    <Area yAxisId="left" type="monotone" dataKey="revenue" name="Revenue (₹)" stroke="#3B82F6" strokeWidth={2} fillOpacity={1} fill="url(#colorRevenue)" />
                    <Bar yAxisId="right" dataKey="quantity" name="Units Sold" fill="#F59E0B" barSize={20} radius={[4, 4, 0, 0]} />
                  </>
                )}

                {chartType === 'line' && (
                  <>
                    <Line yAxisId="left" type="monotone" dataKey="revenue" name="Revenue (₹)" stroke="#3B82F6" strokeWidth={2} dot={{r: 3}} />
                    <Line yAxisId="right" type="monotone" dataKey="quantity" name="Units Sold" stroke="#F59E0B" strokeWidth={2} dot={{r: 3}} />
                  </>
                )}

                {chartType === 'bar' && (
                  <>
                    <Bar yAxisId="left" dataKey="revenue" name="Revenue (₹)" fill="#3B82F6" barSize={20} radius={[4, 4, 0, 0]} />
                    <Bar yAxisId="right" dataKey="quantity" name="Units Sold" fill="#F59E0B" barSize={20} radius={[4, 4, 0, 0]} />
                  </>
                )}

              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Top Revenue Items */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 transition-colors">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4">Top Revenue Drivers</h3>
          <div className="h-80 overflow-y-auto pr-2 custom-scrollbar">
             {topRevenueItems.map((item, idx) => (
                <div key={idx} className="mb-4 last:mb-0">
                   <div className="flex justify-between items-start mb-1">
                      <span className="text-sm font-medium text-gray-800 dark:text-gray-200 truncate max-w-[180px]" title={item.name}>{item.name}</span>
                      <span className="text-sm font-bold text-green-600 dark:text-green-400">{formatCurrency(item.revenue)}</span>
                   </div>
                   <div className="w-full bg-gray-100 dark:bg-slate-700 rounded-full h-1.5 mb-1">
                      <div className="bg-green-500 h-1.5 rounded-full" style={{ width: `${Math.min(100, (item.revenue / (topRevenueItems[0]?.revenue || 1)) * 100)}%` }}></div>
                   </div>
                   <p className="text-xs text-gray-400 dark:text-gray-500">{item.qty} units sold</p>
                </div>
             ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Stock Status Breakdown */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 transition-colors">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4">Stock Health Distribution</h3>
          <div className="flex items-center">
            <div className="h-56 w-1/2">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={stockStatusData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={80}
                    paddingAngle={2}
                    dataKey="value"
                    stroke="none"
                  >
                    {stockStatusData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={STATUS_COLORS[entry.name]} />
                    ))}
                  </Pie>
                  <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="w-1/2 space-y-3">
               {stockStatusData.map((item) => (
                  <div key={item.name} className="flex items-center justify-between text-sm">
                     <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: STATUS_COLORS[item.name] }}></div>
                        <span className="text-gray-600 dark:text-gray-300">{item.name}</span>
                     </div>
                     <span className="font-semibold text-gray-900 dark:text-white">{item.value}</span>
                  </div>
               ))}
            </div>
          </div>
        </div>

        {/* Warehouse Stock */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 transition-colors">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4">Stock by Warehouse (Filtered)</h3>
          <div className="h-56">
             <ResponsiveContainer width="100%" height="100%">
               <BarChart data={warehouseStats} layout="vertical" margin={{ top: 0, right: 30, left: 40, bottom: 0 }}>
                 <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#E5E7EB" className="dark:stroke-slate-700" />
                 <XAxis type="number" hide />
                 <YAxis type="category" dataKey="name" width={120} tick={{ fontSize: 10, fill: '#94a3b8' }} axisLine={false} tickLine={false} />
                 <Tooltip cursor={{fill: 'transparent'}} contentStyle={{ borderRadius: '8px' }} />
                 <Legend wrapperStyle={{ fontSize: '11px' }}/>
                 <Bar dataKey="sellable" name="Sellable" stackId="a" fill="#10B981" radius={[0, 4, 4, 0]} barSize={12} />
                 <Bar dataKey="unsellable" name="Unsellable" stackId="a" fill="#EF4444" radius={[0, 4, 4, 0]} barSize={12} />
               </BarChart>
             </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';

export interface InventoryRecord {
  itemId: string;
  itemName: string;
  brandName: string;
  upc: string;
  uom: string;
  warehouseId: string;
  warehouseName: string;
  netScheduled: number;
  incomingScheduled: number;
  recalled: number;
  totalSellable: number;
  sellableWarehouse: number;
  sellableInBetween: number;
  sellableDarkstore: number;
  totalUnsellable: number;
  unsellableDamaged: number;
  unsellableLost: number;
  unsellableExpired: number;
  unsellableNearExpiry: number;
  soldLast7?: number;
  soldLast15?: number;
  soldLast30?: number;
}

export interface SalesRecord {
  itemId: string;
  itemName?: string;
  brandName?: string;
  quantity: number;
  revenue: number;
  date?: string; // YYYY-MM-DD
}

export interface MergedItem {
  itemId: string;
  itemName: string;
  brandName: string;
  totalSellable: number;
  totalUnsellable: number;
  salesVelocity: number; 
  totalRevenue: number; 
  inventoryRunway: number; 
  warehouseDistribution: { [key: string]: number };
  stockStatus: 'Healthy' | 'Overstocked' | 'Stockout' | 'Low';
}

export interface ChartDataPoint {
  date: string;
  revenue: number;
  quantity: number;
  label: string;
}

export interface DataSource {
  id: string;
  type: FileType;
  fileName: string;
  uploadDate: number;
  isActive: boolean;
  rowCount: number;
  rawContent?: string;
  parsedData?: (InventoryRecord | SalesRecord)[];
}

export type FileType = 'INVENTORY' | 'SALES';

export enum ViewMode {
  DASHBOARD = 'DASHBOARD',
  INVENTORY_LIST = 'INVENTORY_LIST',
  DATA_IMPORT = 'DATA_IMPORT',
  PRODUCT_DETAIL = 'PRODUCT_DETAIL',
}

import React, { useState, useMemo, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { InventoryTable } from './components/InventoryTable';
import { DataImport } from './components/DataImport';
import { ProductDetail } from './components/ProductDetail';
import { parseInventoryCSV, parseSalesCSV, readFileAsText, readExcelAsCSV, mergeData } from './utils';
import { InventoryRecord, SalesRecord, ViewMode, DataSource, FileType } from './types';
import { RAW_CSV_DATA, RAW_SALES_DATA } from './constants';

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.DATA_IMPORT);
  const [sources, setSources] = useState<DataSource[]>([]);
  const [loading, setLoading] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);

  // Initialize theme from system preference or default to light
  useEffect(() => {
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setIsDarkMode(true);
    }
  }, []);

  // Derived active data sets
  const activeInventoryData = useMemo(() => {
    const invSource = sources.find(s => s.type === 'INVENTORY' && s.isActive);
    return (invSource?.parsedData as InventoryRecord[]) || [];
  }, [sources]);

  const activeSalesData = useMemo(() => {
    return sources
      .filter(s => s.type === 'SALES' && s.isActive)
      .flatMap(s => (s.parsedData as SalesRecord[]) || []);
  }, [sources]);

  // Derived merged data for dashboard
  const mergedData = useMemo(() => {
    if (activeInventoryData.length === 0 && activeSalesData.length === 0) return [];
    return mergeData(activeInventoryData, activeSalesData);
  }, [activeInventoryData, activeSalesData]);

  // Handler to open product detail
  const handleSelectProduct = (itemId: string) => {
    setSelectedItemId(itemId);
    setViewMode(ViewMode.PRODUCT_DETAIL);
  };

  const processFileContent = (content: string, type: FileType, fileName: string) => {
    let records: (InventoryRecord | SalesRecord)[] = [];

    if (type === 'INVENTORY') {
      records = parseInventoryCSV(content);
    } else {
      records = parseSalesCSV(content);
    }

    const newSource: DataSource = {
      id: Date.now().toString(),
      type,
      fileName,
      uploadDate: Date.now(),
      isActive: true,
      rowCount: records.length,
      rawContent: content,
      parsedData: records
    };

    setSources(prev => {
      if (type === 'INVENTORY') {
        // Replace existing inventory
        return [...prev.filter(s => s.type !== 'INVENTORY'), newSource];
      } else {
        // Append new sales report
        return [...prev, newSource];
      }
    });
  };

  const handleFileUpload = async (file: File, type: FileType) => {
    try {
      let content = '';
      if (file.name.endsWith('.csv')) {
        content = await readFileAsText(file);
      } else if (file.name.match(/\.(xlsx|xls)$/)) {
        content = await readExcelAsCSV(file);
      } else {
        throw new Error("Unsupported file format. Please upload .csv, .xlsx, or .xls");
      }
      processFileContent(content, type, file.name);
    } catch (error: any) {
      console.error("File processing error:", error);
      throw error; 
    }
  };

  const handleLoadSample = () => {
    setLoading(true);
    setTimeout(() => {
      try {
        const demoInvId = 'demo-inventory';
        const demoSalesId = 'demo-sales';
        const invRecords = parseInventoryCSV(RAW_CSV_DATA);
        const salesRecords = parseSalesCSV(RAW_SALES_DATA);

        setSources(prev => {
          const cleanPrev = prev.filter(s => s.id !== demoInvId && s.id !== demoSalesId);
          return [
            ...cleanPrev,
            {
              id: demoInvId,
              type: 'INVENTORY',
              fileName: 'Demo_Inventory_Data.csv',
              uploadDate: Date.now(),
              isActive: true,
              rowCount: invRecords.length,
              rawContent: RAW_CSV_DATA,
              parsedData: invRecords
            },
            {
              id: demoSalesId,
              type: 'SALES',
              fileName: 'Demo_Monthly_Sales.csv',
              uploadDate: Date.now(),
              isActive: true,
              rowCount: salesRecords.length,
              rawContent: RAW_SALES_DATA,
              parsedData: salesRecords
            }
          ];
        });
        setViewMode(ViewMode.DASHBOARD);
      } catch (e) {
        console.error("Error loading sample data", e);
      } finally {
        setLoading(false);
      }
    }, 800);
  };

  const handleRefreshData = async () => {
    setLoading(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 600));
      setSources(prev => prev.map(source => {
        if (!source.rawContent) return source;
        let records: (InventoryRecord | SalesRecord)[] = [];
        if (source.type === 'INVENTORY') {
          records = parseInventoryCSV(source.rawContent);
        } else {
          records = parseSalesCSV(source.rawContent);
        }
        return { ...source, rowCount: records.length, parsedData: records };
      }));
      alert("Data refreshed successfully.");
    } catch (e) {
      console.error("Refresh failed", e);
      alert("Failed to refresh data.");
    } finally {
      setLoading(false);
    }
  };

  const handleRemoveSource = (id: string) => {
    setSources(prev => prev.filter(s => s.id !== id));
  };

  const handleToggleSource = (id: string) => {
    setSources(prev => prev.map(s => s.id === id ? { ...s, isActive: !s.isActive } : s));
  };

  if (loading) {
    return (
      <div className={`h-screen w-full flex items-center justify-center ${isDarkMode ? 'bg-slate-900' : 'bg-gray-50'}`}>
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-yellow-400"></div>
          <p className={`font-medium animate-pulse ${isDarkMode ? 'text-slate-400' : 'text-gray-500'}`}>Processing Data...</p>
        </div>
      </div>
    );
  }

  return (
    <Layout currentMode={viewMode} setMode={setViewMode} isDarkMode={isDarkMode} toggleTheme={() => setIsDarkMode(!isDarkMode)}>
      {viewMode === ViewMode.DASHBOARD && (
        sources.some(s => s.isActive) ? (
          <Dashboard 
            mergedData={mergedData} 
            rawInventory={activeInventoryData} 
            salesData={activeSalesData}
            onSelectProduct={handleSelectProduct}
          />
        ) : (
          <div className="flex flex-col items-center justify-center h-full text-gray-400 dark:text-slate-500">
             <div className="bg-white dark:bg-slate-800 p-8 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700 text-center max-w-md transition-colors">
                <p className="text-lg font-medium text-gray-800 dark:text-white mb-2">Ready to Analyze?</p>
                <p className="text-gray-500 dark:text-slate-400 mb-6">Upload your inventory and sales reports to see the insights.</p>
                <button 
                  onClick={() => setViewMode(ViewMode.DATA_IMPORT)} 
                  className="px-6 py-2 bg-yellow-400 text-slate-900 font-bold rounded-lg hover:bg-yellow-300 transition-colors"
                >
                  Go to Import
                </button>
             </div>
          </div>
        )
      )}

      {viewMode === ViewMode.INVENTORY_LIST && (
        <InventoryTable 
          data={activeInventoryData} 
          onSelectProduct={handleSelectProduct}
        />
      )}

      {viewMode === ViewMode.PRODUCT_DETAIL && selectedItemId && (
        <ProductDetail
          itemId={selectedItemId}
          mergedData={mergedData}
          rawInventory={activeInventoryData}
          salesData={activeSalesData}
          onBack={() => setViewMode(ViewMode.INVENTORY_LIST)}
        />
      )}

      {viewMode === ViewMode.DATA_IMPORT && (
        <DataImport 
          sources={sources} 
          onUpload={handleFileUpload} 
          onRemove={handleRemoveSource}
          onToggle={handleToggleSource}
          onLoadSample={handleLoadSample}
          onRefresh={handleRefreshData}
        />
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { InventoryRecord } from '../types';
import { Search, ArrowUpDown, ArrowDown, ArrowUp, Filter, IndianRupee } from 'lucide-react';

interface InventoryTableProps {
  data: InventoryRecord[];
  onSelectProduct: (itemId: string) => void;
}

type SortField = keyof InventoryRecord | 'revenue'; // extended for display purposes
type SortOrder = 'asc' | 'desc';

export const InventoryTable: React.FC<InventoryTableProps> = ({ data, onSelectProduct }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [sortField, setSortField] = useState<SortField>('totalSellable');
  const [sortOrder, setSortOrder] = useState<SortOrder>('desc');
  const [showFilters, setShowFilters] = useState(false);

  // Filters State
  const [filters, setFilters] = useState({
    brand: 'All',
    warehouse: 'All',
  });

  // Extract Unique Values
  const uniqueBrands = useMemo(() => Array.from(new Set(data.map(i => i.brandName))).sort(), [data]);
  const uniqueWarehouses = useMemo(() => Array.from(new Set(data.map(i => i.warehouseName))).sort(), [data]);

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('desc');
    }
  };

  const filteredData = data
    .filter(item => {
        const matchesSearch = item.itemName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                              item.itemId.includes(searchTerm);
        const matchesBrand = filters.brand === 'All' || item.brandName === filters.brand;
        const matchesWarehouse = filters.warehouse === 'All' || item.warehouseName === filters.warehouse;

        return matchesSearch && matchesBrand && matchesWarehouse;
    })
    .sort((a, b) => {
      const aValue = a[sortField as keyof InventoryRecord];
      const bValue = b[sortField as keyof InventoryRecord];

      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortOrder === 'asc' ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
      }

      return sortOrder === 'asc' 
        ? (aValue as number) - (bValue as number) 
        : (bValue as number) - (aValue as number);
    });

  const SortIcon = ({ field }: { field: SortField }) => {
    if (sortField !== field) return <ArrowUpDown className="w-4 h-4 text-gray-300" />;
    return sortOrder === 'asc' 
      ? <ArrowUp className="w-4 h-4 text-blue-600" /> 
      : <ArrowDown className="w-4 h-4 text-blue-600" />;
  };

  return (
    <div className="space-y-4">
      {/* Header & Search */}
      <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 transition-colors">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-4">
            <h2 className="text-xl font-bold text-gray-800 dark:text-white">Raw Inventory Data</h2>
            <div className="flex gap-2 w-full md:w-auto">
                <button 
                    onClick={() => setShowFilters(!showFilters)}
                    className={`px-4 py-2 rounded-lg border flex items-center gap-2 text-sm font-medium transition-colors ${
                      showFilters 
                        ? 'bg-slate-100 dark:bg-slate-700 border-slate-300 dark:border-slate-600 text-slate-800 dark:text-white' 
                        : 'bg-white dark:bg-slate-800 border-gray-200 dark:border-slate-600 text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-slate-700'
                    }`}
                >
                    <Filter className="w-4 h-4" />
                    Filters
                </button>
                <div className="relative flex-1 md:w-80">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                    <input
                        type="text"
                        placeholder="Search Product Name or ID..."
                        className="w-full pl-10 pr-4 py-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
            </div>
        </div>

        {/* Expandable Filter Panel */}
        {showFilters && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-4 border-t border-gray-100 dark:border-slate-700 animate-in slide-in-from-top-1">
                <div>
                    <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Warehouse</label>
                    <select 
                        className="w-full p-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm outline-none focus:border-blue-500 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                        value={filters.warehouse}
                        onChange={(e) => setFilters({...filters, warehouse: e.target.value})}
                    >
                        <option value="All">All Warehouses</option>
                        {uniqueWarehouses.map(w => <option key={w} value={w}>{w}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Brand</label>
                    <select 
                        className="w-full p-2 border border-gray-200 dark:border-slate-600 rounded-lg text-sm outline-none focus:border-blue-500 bg-white dark:bg-slate-700 text-gray-800 dark:text-white"
                        value={filters.brand}
                        onChange={(e) => setFilters({...filters, brand: e.target.value})}
                    >
                        <option value="All">All Brands</option>
                        {uniqueBrands.map(b => <option key={b} value={b}>{b}</option>)}
                    </select>
                </div>
                <div className="flex items-end">
                    <button 
                        onClick={() => setFilters({brand: 'All', warehouse: 'All'})}
                        className="text-sm text-blue-600 dark:text-blue-400 hover:underline px-2 py-2"
                    >
                        Clear Filters
                    </button>
                </div>
            </div>
        )}
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden transition-colors">
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-50 dark:bg-slate-700 text-gray-600 dark:text-gray-300 font-medium border-b border-gray-200 dark:border-slate-600">
              <tr>
                <th className="px-6 py-4 cursor-pointer hover:bg-gray-100 dark:hover:bg-slate-600" onClick={() => handleSort('itemName')}>
                  <div className="flex items-center gap-2">Product Details <SortIcon field="itemName" /></div>
                </th>
                <th className="px-6 py-4 cursor-pointer hover:bg-gray-100 dark:hover:bg-slate-600" onClick={() => handleSort('warehouseName')}>
                   <div className="flex items-center gap-2">Warehouse <SortIcon field="warehouseName" /></div>
                </th>
                <th className="px-6 py-4 text-right cursor-pointer hover:bg-gray-100 dark:hover:bg-slate-600" onClick={() => handleSort('totalSellable')}>
                   <div className="flex items-center justify-end gap-2">Sellable <SortIcon field="totalSellable" /></div>
                </th>
                 <th className="px-6 py-4 text-right cursor-pointer hover:bg-gray-100 dark:hover:bg-slate-600" onClick={() => handleSort('sellableDarkstore')}>
                   <div className="flex items-center justify-end gap-2">Darkstore <SortIcon field="sellableDarkstore" /></div>
                </th>
                <th className="px-6 py-4 text-right cursor-pointer hover:bg-gray-100 dark:hover:bg-slate-600" onClick={() => handleSort('totalUnsellable')}>
                   <div className="flex items-center justify-end gap-2">Unsellable <SortIcon field="totalUnsellable" /></div>
                </th>
                <th className="px-6 py-4 text-right cursor-pointer hover:bg-gray-100 dark:hover:bg-slate-600" onClick={() => handleSort('unsellableDamaged')}>
                   <div className="flex items-center justify-end gap-2">Damaged <SortIcon field="unsellableDamaged" /></div>
                </th>
                <th className="px-6 py-4 text-right cursor-pointer hover:bg-gray-100 dark:hover:bg-slate-600" onClick={() => handleSort('soldLast30')}>
                   <div className="flex items-center justify-end gap-2">Sold (30d) <SortIcon field="soldLast30" /></div>
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
              {filteredData.map((record, idx) => (
                <tr 
                  key={`${record.itemId}-${record.warehouseId}-${idx}`} 
                  onClick={() => onSelectProduct(record.itemId)}
                  className="hover:bg-blue-50 dark:hover:bg-slate-700/60 cursor-pointer transition-colors group"
                >
                  <td className="px-6 py-4 max-w-xs">
                    <div className="font-medium text-gray-900 dark:text-gray-100 truncate group-hover:text-blue-600 dark:group-hover:text-blue-400" title={record.itemName}>{record.itemName}</div>
                    <div className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">ID: {record.itemId} | {record.brandName}</div>
                  </td>
                  <td className="px-6 py-4 text-gray-600 dark:text-gray-400">{record.warehouseName}</td>
                  <td className="px-6 py-4 text-right font-medium text-green-600 dark:text-green-400 bg-green-50/50 dark:bg-green-900/20">{record.totalSellable}</td>
                  <td className="px-6 py-4 text-right text-gray-600 dark:text-gray-400">{record.sellableDarkstore}</td>
                  <td className="px-6 py-4 text-right font-medium text-red-600 dark:text-red-400 bg-red-50/50 dark:bg-red-900/20">{record.totalUnsellable}</td>
                  <td className="px-6 py-4 text-right text-gray-600 dark:text-gray-400">{record.unsellableDamaged}</td>
                  <td className="px-6 py-4 text-right text-blue-600 dark:text-blue-400 font-medium">{record.soldLast30}</td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-6 py-12 text-center text-gray-400 dark:text-gray-500">
                    No records found matching your filters.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { InventoryRecord, MergedItem, SalesRecord } from '../types';
import { aggregateByWarehouse, prepareSalesChartData } from '../utils';
import { 
  ComposedChart, Bar, BarChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell, Area
} from 'recharts';
import { Package, AlertTriangle, TrendingUp, ArchiveX, Filter, IndianRupee, X, Download, Activity, BarChart2, Layers } from 'lucide-react';

interface DashboardProps {
  mergedData: MergedItem[];
  rawInventory: InventoryRecord[];
  salesData: SalesRecord[];
  onSelectProduct: (itemId: string) => void;
}

const COLORS = ['#10B981', '#F59E0B', '#EF4444', '#3B82F6', '#8B5CF6'];
const STATUS_COLORS: {[key: string]: string} = {
  'Healthy': '#10B981',
  'Overstocked': '#F59E0B',
  'Low Stock': '#3B82F6',
  'Stockout': '#EF4444'
};

export const Dashboard: React.FC<DashboardProps> = ({ mergedData, rawInventory, salesData, onSelectProduct }) => {
  const [chartPeriod, setChartPeriod] = useState<'daily' | 'weekly' | 'monthly'>('daily');
  const [chartType, setChartType] = useState<'mixed' | 'line' | 'bar'>('mixed');
  const [filters, setFilters] = useState({
    brand: 'All',
    status: 'All',
    warehouse: 'All'
  });
  const [showFilters, setShowFilters] = useState(false);

  // --- Derived Data for Filters ---
  const uniqueBrands = useMemo(() => Array.from(new Set(mergedData.map(i => i.brandName))).sort(), [mergedData]);
  const uniqueWarehouses = useMemo(() => Array.from(new Set(rawInventory.map(i => i.warehouseName))).sort(), [rawInventory]);

  // --- Filter Logic ---
  const filteredData = useMemo(() => {
    return mergedData.filter(item => {
      const matchBrand = filters.brand === 'All' || item.brandName === filters.brand;
      const matchStatus = filters.status === 'All' || item.stockStatus === filters.status;
      const matchWarehouse = filters.warehouse === 'All' || item.warehouseDistribution[filters.warehouse] > 0;
      return matchBrand && matchStatus && matchWarehouse;
    });
  }, [mergedData, filters, rawInventory]);

  // Filter raw inventory for Warehouse chart
  const filteredInventory = useMemo(() => {
    return rawInventory.filter(item => {
      const matchBrand = filters.brand === 'All' || item.brandName === filters.brand;
      const matchWarehouse = filters.warehouse === 'All' || item.warehouseName === filters.warehouse;
      return matchBrand && matchWarehouse;
    });
  }, [rawInventory, filters]);

  // Filter sales data for charts (by Brand only as Warehouse ID missing in Sales)
  const filteredSales = useMemo(() => {
    return salesData.filter(sale => {
      const matchBrand = filters.brand === 'All' || (sale.brandName && sale.brandName === filters.brand);
      return matchBrand;
    });
  }, [salesData, filters.brand]);

  // --- Aggregations ---
  const warehouseStats = useMemo(() => aggregateByWarehouse(filteredInventory), [filteredInventory]);
  const chartData = useMemo(() => prepareSalesChartData(filteredSales), [filteredSales]);

  // KPIs
  const totalSellable = filteredData.reduce((sum, r) => sum + r.totalSellable, 0);
  const totalUnsellable = filteredData.reduce((sum, r) => sum + r.totalUnsellable, 0);
  const totalRevenue = filteredData.reduce((sum, r) => sum + r.totalRevenue, 0);
  const totalSalesVelocity = filteredData.reduce((sum, r) => sum + r.salesVelocity, 0);

  const unsellableRatio = totalSellable + totalUnsellable > 0 
    ? ((totalUnsellable / (totalSellable + totalUnsellable)) * 100).toFixed(1)
    : "0";

  // Top Selling Items (by Revenue)
  const topRevenueItems = [...filteredData]
    .sort((a, b) => b.totalRevenue - a.totalRevenue)
    .slice(0, 5)
    .map(item => ({
      id: item.itemId,
      name: item.itemName.length > 20 ? item.itemName.substring(0, 20) + '...' : item.itemName,
      fullName: item.itemName,
      revenue: item.totalRevenue,
      qty: item.salesVelocity
    }));

  // Stock Status Distribution
  const stockStatusData = [
    { name: 'Healthy', value: filteredData.filter(i => i.stockStatus === 'Healthy').length },
    { name: 'Overstocked', value: filteredData.filter(i => i.stockStatus === 'Overstocked').length },
    { name: 'Low Stock', value: filteredData.filter(i => i.stockStatus === 'Low').length },
    { name: 'Stockout', value: filteredData.filter(i => i.stockStatus === 'Stockout').length },
  ].filter(x => x.value > 0);

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0
    }).format(val);
  };

  const handleExportChartData = () => {
    const data = chartData[chartPeriod];
    if (!data || data.length === 0) return;

    const csvRows = [
      ['Date', 'Period Label', 'Revenue (INR)', 'Units Sold'],
      ...data.map(row => [
        row.date,
        row.label,
        row.revenue,
        row.quantity
      ])
    ];

    const csvContent = "data:text/csv;charset=utf-8," + csvRows.map(e => e.join(",")).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `blinkit_sales_trend_${chartPeriod}_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
