import React, { useMemo, useState } from 'react';
import { InventoryRecord, MergedItem, SalesRecord, ChartDataPoint } from '../types';
import { prepareSalesChartData } from '../utils';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  LineChart, Line, ComposedChart, Area
} from 'recharts';
import { 
  ArrowLeft, Package, AlertTriangle, TrendingUp, ArchiveX, MapPin, 
  ExternalLink, Search, Box, Calendar, AlertOctagon, Download, Sparkles
} from 'lucide-react';

interface ProductDetailProps {
  itemId: string;
  mergedData: MergedItem[];
  rawInventory: InventoryRecord[];
  salesData: SalesRecord[];
  onBack: () => void;
}

export const ProductDetail: React.FC<ProductDetailProps> = ({ itemId, mergedData, rawInventory, salesData, onBack }) => {

  // Get main item summary
  const product = mergedData.find(i => i.itemId === itemId);

  // Get raw inventory rows for this item (for warehouse breakdown)
  const productInventory = useMemo(() => 
    rawInventory.filter(r => r.itemId === itemId), 
  [rawInventory, itemId]);

  // Get raw sales rows for this item (for charts)
  const productSales = useMemo(() => 
    salesData.filter(s => s.itemId === itemId), 
  [salesData, itemId]);

  // Warehouse Chart Data
  const warehouseChartData = useMemo(() => {
    return productInventory.map(inv => ({
      name: inv.warehouseName.replace(' - Feeder', '').replace('Bengaluru', 'BLR').replace('Mumbai', 'MUM'),
      sellable: inv.totalSellable,
      unsellable: inv.totalUnsellable,
      damaged: inv.unsellableDamaged,
      expired: inv.unsellableExpired
    })).sort((a, b) => b.sellable - a.sellable);
  }, [productInventory]);

  // Sales Chart Data
  const salesChartData = useMemo(() => prepareSalesChartData(productSales).daily, [productSales]);

  // --- Forecasting Logic ---
  const forecastData = useMemo(() => {
    if (salesChartData.length < 2) return [];

    // 1. Fill in missing dates with 0 sales for accurate trend analysis
    const sortedData = [...salesChartData].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    const fullHistory: { date: string; timestamp: number; quantity: number }[] = [];

    if (sortedData.length > 0) {
      const startDate = new Date(sortedData[0].date);
      const endDate = new Date(sortedData[sortedData.length - 1].date);

      for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
        const dateStr = d.toISOString().split('T')[0];
        const existing = sortedData.find(item => item.date === dateStr);
        fullHistory.push({
          date: dateStr,
          timestamp: d.getTime(),
          quantity: existing ? existing.quantity : 0
        });
      }
    }

    // 2. Calculate Linear Regression (y = mx + b)
    const n = fullHistory.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0;

    fullHistory.forEach(p => {
        sumX += p.timestamp;
        sumY += p.quantity;
        sumXY += (p.timestamp * p.quantity);
        sumXX += (p.timestamp * p.timestamp);
    });

    const slope = (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    // 3. Generate Forecast Points (Next 30 Days)
    const combinedData = fullHistory.map(item => ({
      date: item.date,
      label: item.date, // formatting could be improved
      actual: item.quantity,
      forecast: null as number | null
    }));

    const lastHistPoint = fullHistory[fullHistory.length - 1];
    const lastDate = new Date(lastHistPoint.date);

    // Connect the last actual point to the forecast line start
    const lastTrendValue = Math.max(0, slope * lastHistPoint.timestamp + intercept);

    // We add a point at the last date that has both actual and "start of forecast" to connect lines visually if needed,
    // or we just start generating from next day. 
    // Let's create a transition point.

    for (let i = 1; i <= 30; i++) {
        const nextDate = new Date(lastDate);
        nextDate.setDate(lastDate.getDate() + i);
        const nextTimestamp = nextDate.getTime();

        // y = mx + b
        const prediction = Math.max(0, slope * nextTimestamp + intercept);

        combinedData.push({
            date: nextDate.toISOString().split('T')[0],
            label: nextDate.toISOString().split('T')[0],
            actual: null,
            forecast: parseFloat(prediction.toFixed(1))
        });
    }

    // Fix: Ensure the line connects by setting the forecast value of the last actual point
    const lastIndex = fullHistory.length - 1;
    if (combinedData[lastIndex]) {
        combinedData[lastIndex].forecast = combinedData[lastIndex].actual; 
    }

    return combinedData;
  }, [salesChartData]);

  const totalForecastedSales = useMemo(() => {
     return forecastData.reduce((acc, curr) => acc + (curr.forecast || 0), 0).toFixed(0);
  }, [forecastData]);


  if (!product) {
