import React, { useState } from 'react';
import { Upload, FileText, Trash2, Eye, EyeOff, CheckCircle, FileSpreadsheet, AlertCircle, X, RefreshCw, Plus, Megaphone } from 'lucide-react';
import { DataSource, FileType } from '../types';

interface DataImportProps {
  sources: DataSource[];
  onUpload: (file: File, type: FileType) => Promise<void>;
  onRemove: (id: string) => void;
  onToggle: (id: string) => void;
  onLoadSample: () => void;
  onRefresh: () => void;
}

export const DataImport: React.FC<DataImportProps> = ({ sources, onUpload, onRemove, onToggle, onLoadSample, onRefresh }) => {
  const [uploadingType, setUploadingType] = useState<FileType | null>(null);
  const [error, setError] = useState<{ type: FileType; message: string } | null>(null);
  const [progress, setProgress] = useState(0);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, type: FileType) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setUploadingType(type);
      setError(null);
      setProgress(0);

      const interval = setInterval(() => {
        setProgress(prev => {
          if (prev >= 90) return prev;
          return prev + 10;
        });
      }, 100);

      try {
        await onUpload(file, type);
        setProgress(100);
        // Reset file input value so same file can be selected again
        e.target.value = '';
      } catch (err: any) {
        setError({ type, message: err.message || "Failed to parse file." });
      } finally {
        clearInterval(interval);
        setTimeout(() => {
          setUploadingType(null);
          setProgress(0);
        }, 500);
      }
    }
  };

  const UploadCard = ({ type, title, description, allowedExts, multiple, icon: Icon }: { type: FileType, title: string, description: string, allowedExts: string, multiple: boolean, icon: any }) => {
    const existingFiles = sources.filter(s => s.type === type);
    const isUploading = uploadingType === type;
    const hasError = error?.type === type;

    // For single file mode, show input if no file exists.
    // For multiple file mode, always show input.
    const showInput = multiple || existingFiles.length === 0;

    return (
      <div className={`flex flex-col h-full p-6 rounded-xl border-2 border-dashed transition-all relative overflow-hidden ${
        existingFiles.length > 0
          ? 'border-green-200 bg-green-50 dark:bg-green-900/10 dark:border-green-800' 
          : hasError 
            ? 'border-red-200 bg-red-50 dark:bg-red-900/10 dark:border-red-800' 
            : 'border-gray-200 hover:border-yellow-400 bg-white dark:bg-slate-800 dark:border-slate-700 dark:hover:border-yellow-500'
      }`}>
        {/* Loading Overlay */}
        {isUploading && (
          <div className="absolute inset-0 bg-white/90 dark:bg-slate-800/90 z-20 flex flex-col items-center justify-center p-6">
            <div className="w-full max-w-[200px] h-2 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden mb-3">
              <div 
                className="h-full bg-yellow-400 transition-all duration-300 ease-out"
                style={{ width: `${progress}%` }}
              />
            </div>
            <p className="text-sm font-medium text-gray-600 dark:text-gray-300 animate-pulse">Processing File...</p>
          </div>
        )}

        <div className="flex items-start justify-between mb-4">
          <div className="flex items-center gap-3">
             <div className={`p-3 rounded-lg ${
               existingFiles.length > 0 ? 'bg-green-100 text-green-600 dark:bg-green-900 dark:text-green-400' : 
               hasError ? 'bg-red-100 text-red-600 dark:bg-red-900 dark:text-red-400' : 'bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400'
             }`}>
               {existingFiles.length > 0 ? <CheckCircle className="w-6 h-6" /> : <Icon className="w-6 h-6" />}
             </div>
             <div>
               <h3 className="font-bold text-gray-800 dark:text-gray-100">{title}</h3>
               <p className="text-sm text-gray-500 dark:text-gray-400 max-w-xs">{description}</p>
             </div>
          </div>
        </div>

        {hasError && (
          <div className="mb-4 p-3 bg-red-100 dark:bg-red-900/30 border border-red-200 dark:border-red-800 rounded-lg flex items-start gap-2 text-sm text-red-700 dark:text-red-300 animate-in slide-in-from-top-2">
            <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="font-semibold">Error Uploading File</p>
              <p className="mt-1">{error.message}</p>
            </div>
            <button onClick={() => setError(null)} className="text-red-500 hover:text-red-800 dark:hover:text-red-300">
              <X className="w-4 h-4" />
            </button>
          </div>
        )}

        {/* List of uploaded files */}
        <div className="flex-1 space-y-2 mb-4">
          {existingFiles.map(file => (
            <div key={file.id} className="p-3 bg-white/60 dark:bg-slate-900/50 rounded-lg border border-green-100 dark:border-green-800/30 flex justify-between items-center animate-in fade-in slide-in-from-bottom-1">
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  <span className={`font-medium text-sm truncate ${!file.isActive ? 'text-gray-400 line-through' : 'text-gray-700 dark:text-gray-300'}`} title={file.fileName}>
                    {file.fileName}
                  </span>
                  {!file.isActive && <span className="text-xs text-red-500 font-medium">(Hidden)</span>}
                </div>
                <div className="text-xs text-gray-400 dark:text-gray-500 mt-0.5">
                   {file.rowCount.toLocaleString()} rows • {new Date(file.uploadDate).toLocaleTimeString()}
                </div>
              </div>
              <div className="flex gap-1 ml-2">
                 <button 
                    onClick={() => onToggle(file.id)}
                    className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-white dark:hover:bg-slate-700 rounded transition-colors"
                    title={file.isActive ? "Hide Data" : "Show Data"}
                  >
                    {file.isActive ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                 </button>
                 <button 
                    onClick={() => onRemove(file.id)}
                    className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-white dark:hover:bg-slate-700 rounded transition-colors"
                    title="Remove File"
                  >
                    <Trash2 className="w-4 h-4" />
                 </button>
              </div>
            </div>
          ))}
        </div>

        {/* Upload Button */}
        {showInput && (
          <div className="mt-auto">
            <label className={`flex items-center justify-center w-full px-4 py-3 border border-gray-200 dark:border-slate-600 rounded-lg shadow-sm cursor-pointer transition-colors group ${
              multiple && existingFiles.length > 0 
                ? 'bg-slate-50 dark:bg-slate-800 border-dashed hover:bg-slate-100 dark:hover:bg-slate-700' 
                : 'bg-white dark:bg-slate-700 hover:bg-gray-50 dark:hover:bg-slate-600'
            }`}>
              {multiple && existingFiles.length > 0 ? (
                 <Plus className="w-5 h-5 mr-2 text-gray-400 dark:text-gray-300 group-hover:text-green-500" />
              ) : (
                 <Upload className="w-5 h-5 mr-2 text-gray-400 dark:text-gray-300 group-hover:text-yellow-500" />
              )}
              <span className="text-sm font-medium text-gray-600 dark:text-gray-200 group-hover:text-gray-900 dark:group-hover:text-white">
                {multiple && existingFiles.length > 0 ? "Add Another Report" : `Upload ${allowedExts}`}
              </span>
              <input 
                type="file" 
                className="hidden" 
                accept=".csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel" 
                onChange={(e) => handleFileChange(e, type)} 
              />
            </label>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Data Management</h2>
          <p className="text-gray-500 dark:text-gray-400 mt-1">Upload your Blinkit reports to power the analytics engine.</p>
        </div>
        {sources.length > 0 && (
          <button 
            onClick={onRefresh}
            className="flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-gray-700 dark:text-gray-200 rounded-lg transition-colors text-sm font-medium"
          >
            <RefreshCw className="w-4 h-4" />
            Refresh Data
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <UploadCard 
          type="INVENTORY" 
          title="Warehouse Stock" 
          description="Inventory sheet with warehouse stock levels. (Single File)"
          allowedExts="CSV or Excel"
          multiple={false}
          icon={FileSpreadsheet}
        />
        <UploadCard 
          type="SALES" 
          title="Sales Reports" 
          description="Sales reports to aggregate sales velocity and revenue. (Multiple Files)"
          allowedExts="CSV or Excel"
          multiple={true}
          icon={FileText}
        />
        <UploadCard 
          type="ADVERTISEMENT" 
          title="Ads Report" 
          description="Blinkit Advertising Campaign Reports. (Multiple Files)"
          allowedExts="CSV or Excel"
          multiple={true}
          icon={Megaphone}
        />
      </div>

      <div className="pt-8 border-t border-gray-200 dark:border-slate-800">
        <div className="bg-gradient-to-r from-slate-900 to-slate-800 rounded-xl p-6 text-white flex items-center justify-between shadow-lg">
          <div>
            <h3 className="font-bold text-lg">Don't have files handy?</h3>
            <p className="text-slate-300 text-sm mt-1">Load sample Blinkit seller data to preview the dashboard.</p>
          </div>
          <button 
            onClick={onLoadSample}
            className="px-6 py-2 bg-yellow-400 text-slate-900 font-bold rounded-lg hover:bg-yellow-300 transition-colors shadow-lg hover:shadow-yellow-400/20"
          >
            Load Demo Data
          </button>
        </div>
      </div>

      {sources.length === 0 && (
         <div className="text-center py-12 text-gray-400 dark:text-slate-600">
            <div className="mb-3">
               <FileText className="w-12 h-12 mx-auto opacity-20" />
            </div>
            <p>No data sources active. Please upload files or load demo data.</p>
         </div>
      )}
    </div>
  );
};

