interface CityDetailProps {
  cityName: string;
  salesData: SalesRecord[];
  onBack: () => void;
  onSelectProduct: (itemId: string) => void;
}

const COLORS = ['#8B5CF6', '#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#EC4899'];

export const CityDetail: React.FC<CityDetailProps> = ({ cityName, salesData, onBack, onSelectProduct }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Filter data for this city
  const citySales = useMemo(() => 
    salesData.filter(s => s.customerCity === cityName), 
  [salesData, cityName]);

  // Aggregate by Product
  const productStats = useMemo(() => {
    const map = new Map<string, { itemId: string; name: string; brand: string; revenue: number; quantity: number }>();

    citySales.forEach(s => {
      if (!map.has(s.itemId)) {
        map.set(s.itemId, { 
          itemId: s.itemId, 
          name: s.itemName || `Item ${s.itemId}`, 
          brand: s.brandName || 'Unknown', 
          revenue: 0, 
          quantity: 0 
        });
      }
      const entry = map.get(s.itemId)!;
      entry.revenue += s.revenue;
      entry.quantity += s.quantity;
    });

    return Array.from(map.values()).sort((a, b) => b.revenue - a.revenue);
  }, [citySales]);

  // KPI Calculations
  const totalRevenue = productStats.reduce((sum, p) => sum + p.revenue, 0);
  const totalUnits = productStats.reduce((sum, p) => sum + p.quantity, 0);
  const uniqueProducts = productStats.length;
  const topBrand = productStats.length > 0 ? productStats[0].brand : 'N/A';

  // Chart Data (Top 5 Categories/Brands could be better, but let's do Top 5 Products by Revenue)
  const chartData = productStats.slice(0, 5).map(p => ({
    name: p.name.length > 20 ? p.name.substring(0, 20) + '...' : p.name,
    value: p.revenue
  }));

  const formatCurrency = (val: number) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(val);

  // Filtered list for table
  const filteredProducts = productStats.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    p.itemId.includes(searchTerm)
  );

  return (
    <div className="space-y-6 animate-in slide-in-from-right-4 duration-300 pb-10">

      {/* Header */}
      <div className="flex items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl border border-gray-100 dark:border-slate-700 shadow-sm">
        <button 
          onClick={onBack}
          className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-slate-700 transition-colors text-gray-600 dark:text-gray-300"
        >
          <ArrowLeft className="w-5 h-5" />
        </button>
        <div>
          <h1 className="text-xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
            <MapPin className="w-5 h-5 text-purple-600" />
            {cityName}
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400">Regional Sales Performance Analysis</p>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-slate-800 p-5 rounded-xl border border-gray-100 dark:border-slate-700 shadow-sm">
           <div className="flex justify-between items-start">
              <div>
                 <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Total City Revenue</p>
                 <h3 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{formatCurrency(totalRevenue)}</h3>
              </div>
              <div className="p-2 bg-purple-50 dark:bg-purple-900/20 rounded-lg">
                 <IndianRupee className="w-5 h-5 text-purple-600 dark:text-purple-400" />
              </div>
           </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-5 rounded-xl border border-gray-100 dark:border-slate-700 shadow-sm">
           <div className="flex justify-between items-start">
              <div>
                 <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Units Sold</p>
                 <h3 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{totalUnits.toLocaleString()}</h3>
              </div>
              <div className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                 <ShoppingBag className="w-5 h-5 text-blue-600 dark:text-blue-400" />
              </div>
           </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-5 rounded-xl border border-gray-100 dark:border-slate-700 shadow-sm">
           <div className="flex justify-between items-start">
              <div>
                 <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Unique Products</p>
                 <h3 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{uniqueProducts}</h3>
              </div>
              <div className="p-2 bg-green-50 dark:bg-green-900/20 rounded-lg">
                 <TrendingUp className="w-5 h-5 text-green-600 dark:text-green-400" />
              </div>
           </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-5 rounded-xl border border-gray-100 dark:border-slate-700 shadow-sm">
           <div className="flex justify-between items-start">
              <div>
                 <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Top Brand</p>
                 <h3 className="text-lg font-bold text-gray-900 dark:text-white mt-1 truncate max-w-[150px]" title={topBrand}>{topBrand}</h3>
